/*
 * Gaudi3 HBM Memory Management
 * ============================
 *
 * The MMU supports a wide range of page sizes (any power-of-2 pages in the
 * range [32MB, 2GB] except 128MB). This set is constant and denoted in this doc as
 * "HMMU supported page size set"
 *
 * Gaudi3 HBM MMU (HMMU) uses MMU V3 arch with some new features:
 *
 *
 * 1. Multiple page sizes: The MMU supports working with up to 3 different page
 *    sizes simultaneously. For example, we can work with the set of pages {32M, 64M, 1G}.
 *    This set is denoted in this doc as "HMMU page size working set".
 *    "HMMU page size working set" should be explicitly configured to the MMU.
 *
 * 2. HOP structure: The MMU has 3 HOPs (0-2). Pages in the range [256M, 2GB] are
 *    configured in HOP1. Pages in the range [32M, 64M] are configured in HOP2. Page
 *    Table Entry (PTE) in HOP1 maps a page of size 256MB and PTE in HOP2 maps a page of
 *    size 1MB. NOTE: while 1MB page is not supported for the user it is the granularity
 *    in which we configure pages in HOP2 (see example in "TLB optimization").
 *
 * 3. TLB optimization: The MMU HW is designed to take advantage of bigger pages
 *    to reduce number of entries in the TLB (but not in the page tables). This is done by
 *    setting the TLB_PageSize field (bits 7:4) in the PTE and this way "hints" the HW to
 *    spare TLB entries.
 *    Example: mapping 32MB page:
 *    - allocate 32M aligned contiguous memory on device memory
 *    - allocate 32M aligned contiguous VA block
 *    - map virt_addr + (i * 1M) -> phys_addr + (i * 1M) where i in [0, 31]
 *    - set bits 7:4 in each PTE to 0x5. 0x5 is the TLB code for 32MB page
 *
 *
 * Driver behavior, variables and default values:
 *
 * HMMU page size working set
 *     The driver has a bitmask in the MMU properties to store the
 *     "HMMU page size working set". The MMU property is called "supported_pages_mask".
 *     The default value is defined by the macro HMMU_DEFAULT_PAGE_SIZE_MASK and can be
 *     modified by the user using a BFE flag (bfe_hmmu_supported_pages_mask) to any
 *     set of up to 3 page sizes exist in "HMMU supported page size set"
 *
 * DRAM page size
 *     This value (dram_page_size which is an ASIC property) does not have any hard
 *     restriction from the HW point-of-view. Rather, the driver should make a smart
 *     decision to optimized memory allocation scheme. According to the above the
 *     DRAM page size will be the smallest in "HMMU page size working set".
 *
 * DRAM allocations without specifying the page size
 *     Due to the requirement for the DRAM page to be contiguous, the driver must be aware
 *     of what page size is used in the allocation.
 *     The user may use the default allocation function (default meaning not specifying
 *     allocation page size) in which case he will get his memory allocated with the "default
 *     device allocation page size". The driver has an ASIC property to this value
 *     (device_mem_alloc_default_page_size) with the default value set by the driver in the
 *     set_fixed_propeties function. The user may choose to set this to other value from
 *     "HMMU page size working set" using BFE flag.
 *
 * DRAM allocations with page size specified
 *     The driver exposes API for the user in which the user can specify the requested page
 *     size for the allocation. See memory IOCTLs in the UAPI.
 */

