#define IS_PDMA_0_ON_DIE0(initiator)						\
		((initiator) >= GAUDI3_DIE0_ENGINE_ID_PDMA_0_CH_0 &&		\
		(initiator) <= GAUDI3_DIE0_ENGINE_ID_PDMA_0_CH_5)

#define IS_PDMA_1_ON_DIE0(initiator)	IS_PDMA_0_ON_DIE0((initiator) - NUM_OF_PDMA_CH_PER_GRP)

#define IS_PDMA_0_ON_DIE1(initiator)						\
		((initiator) >= GAUDI3_DIE1_ENGINE_ID_PDMA_0_CH_0 &&		\
		(initiator) <= GAUDI3_DIE1_ENGINE_ID_PDMA_0_CH_5)

#define IS_PDMA_1_ON_DIE1(initiator)	IS_PDMA_0_ON_DIE1((initiator) - NUM_OF_PDMA_CH_PER_GRP)

