/*
 * type of MME iterator
 * - MME_ITER_BASES iterate all enabled MMEs, each iterator supplied the MME's DCORE offset.
 * - MME_ITER_V3_MSTR_IFS iterate all MME's MSTR_IF V3 blocks, each iterator supplied the
 *                        MME's MSTR_IF_V3 base (AXUSER_HBW_HB_MMU_BYPASS).
 */
enum mme_iter_type {
	MME_ITER_BASES,
	MME_ITER_V3_MSTR_IFS,
};

/*
 * the below enumeration is shared between:
 * - DTLB.CNTRL_PAGE_SIZE.TYPE[1/2/3]_PAGE_SIZE
 * - STLB.CNTRL_PAGE_SIZE.TYPE[1/2/3]_PAGE_SIZE
 * the values can be found in the description
 */
enum hmmu_tlb_ctrl_page_size {
	TLB_CNTRL_PAGE_SIZE_1M,
	TLB_CNTRL_PAGE_SIZE_2M,
	TLB_CNTRL_PAGE_SIZE_4M,
	TLB_CNTRL_PAGE_SIZE_8M,
	TLB_CNTRL_PAGE_SIZE_16M,
	TLB_CNTRL_PAGE_SIZE_32M,
	TLB_CNTRL_PAGE_SIZE_64M,
	TLB_CNTRL_PAGE_SIZE_RSVD,
	TLB_CNTRL_PAGE_SIZE_256M,
	TLB_CNTRL_PAGE_SIZE_512M,
	TLB_CNTRL_PAGE_SIZE_1G,
	TLB_CNTRL_PAGE_SIZE_2G,
	TLB_CNTRL_PAGE_SIZE_NUMBER,
};

#define HMMU_DEFAULT_PAGE_SIZE_MASK	(PAGE_SIZE_32MB | PAGE_SIZE_1GB)

/*
 * struct gaudi3_mmu_maint_data - MMU maintenance operation data
 * @start_addr: maintenance start address.
 * @end_addr: maintenance end address.
 * @timeout_usec: timeout for waiting for maintenance operation to complete.
 * @maint_type: the maintenance operation type (invalidation/prefetch).
 * @range_maint: true for range maintenance, otherwise false.
 * @asid: ASID for maintenance operation.
 */
struct gaudi3_mmu_maint_data {
	u64 start_addr;
	u64 end_addr;
	u64 timeout_usec;
	enum gaudi3_cache_maint_type maint_type;
	bool range_maint;
	u8 asid;
};

/*
 * struct gaudi3_pdma_job_params - PDMA job data
 * @job_str: string describing the JOB, used for logging.
 * @src: PDMA source address.
 * @dst: PDMA destination address.
 * @ch_idx: channel index ranging from 0-23.
 * @ch_reg_base: base address for PDMA channel registers.
 * @size: PDMA transfer size.
 * @is_memset: true if memset, otherwise false.
 */
struct gaudi3_pdma_job_params {
	char job_str[HL_STR_MAX];
	u64 src;
	u64 dst;
	u32 ch_idx;
	u32 ch_reg_base;
	u32 size;
	bool is_memset;
};

/*
 * struct gaudi3_test_pdma_params - PDMA parameters needed for PDMA-testing
 * @host_ptr: host virt address used by the driver.
 * @host_va: The mapped host address in device VA space.
 * @host_mem_dma_addr: host memory bus address, used in DMA transfers.
 * @device_va: device address (dram or sram) mapped in device VA space..
 * @device_pys_address: the device physical address (dram or sram) to be used.
 * @transfer_size: total data to be transferred when all channels are active.
 * @channel_transfer_size: Transfer size of each individual channel (must be multiple of 4).
 * @num_active_channels: number of active dma channels.
 * @region_type: the device region (dram or sram) to test with.
 */
struct gaudi3_test_pdma_params {
	u32 *host_ptr;
	u64 host_va;
	dma_addr_t host_mem_dma_addr;
	u64 device_va;
	u64 device_phys_addr;
	int transfer_size;
	int channel_transfer_size;
	int num_active_channels;
	enum pci_region region_type;
};
/*
 * struct gaudi3_cq_mode_params - handles CQ mode completion
 * @job: the operation that should trigger the CQ completion.
 * @job_data: private data to the op function.
 * @job_str: string describing the JOB.
 * @timeout_usec: timeout for waiting for CQ completion.
 * @target_sob_value: target SOB value.
 * @sob_id: the signaled SOB ID.
 * @mon_id: the monitor used for the completion.
 * @cq_id: CQ ID.
 */
struct gaudi3_cq_mode_params {
	void (*job)(struct hl_device *hdev, void *data);
	void *job_data;
	char *job_str;
	u64 timeout_usec;
	u32 target_sob_value;
	enum gaudi3_reserved_sob_id sob_id;
	enum gaudi3_reserved_mon_id mon_id;
	enum gaudi3_reserved_cq_id cq_id;
};

/*
 * struct gaudi3_stlb_data - data used by STLB iterators and callbacks.
 * @maint_params: data for cache maintenance.
 * @timeout_usec: timeout to wait for the invalidation in usec.
 */
struct gaudi3_stlb_data {
	struct gaudi3_mmu_maint_data *maint_params;
	u32 flags;
};

struct gaudi3_idle_data {
	struct engines_data *e;
	unsigned long *mask;
	bool *is_idle;
};

/*
 * struct gaudi3_mstr_if_dbg_block_operation - function and data used by MSTR_IF.DBG iterator.
 * @func: function to apply to each MSTR_IF.DBG_{H,L}BW block.
 * @dbg_hbw_base_addr: base address of MSTR_IF.DBG_HBW sub-block. 0x0 if not exist in MSTR_IF.
 * @dbg_lbw_base_addr: base address of MSTR_IF.DBG_LBW sub-block. 0x0 if not exist in MSTR_IF.
 */
struct gaudi3_mstr_if_dbg_block_operation {
	void (*func)(struct hl_device *hdev, struct gaudi3_mstr_if_dbg_block_operation *operation);
	u32 dbg_hbw_base_addr;
	u32 dbg_lbw_base_addr;
};

