static void gaudi3_stall_edma_engine(struct hl_device *hdev, int hdcore, int inst, u32 offset,
					struct iterate_module_ctx *ctx)
{
	u32 edma_cmn_reg_base = mmHD1_SEDMA0_CMN_BASE + offset;

	WREG32(edma_cmn_reg_base + mmEDMA_CMN_CFG,
			FIELD_PREP(EDMA_CMN_CFG_HALT_ALL_M, 0x1));
}

