static void gaudi3_stop_decoder_engine(struct hl_device *hdev, int hdcore, int inst, u32 offset,
					struct iterate_module_ctx *ctx)
{
	u32 vcmd_reg_base, dec_reg_base, brdg_ctrl_reg_base, timeout_usec, graceful;
	int rc;

	/* Disable VCMD */
	vcmd_reg_base = mmHD0_VDEC0_CMD_BASE + offset;
	WREG32(vcmd_reg_base + mmVSI_CMD_SWREG16,
			FIELD_PREP(VSI_CMD_SWREG16_SW_START_TRIGGER_M, 0x0));

	/* Disable decoder */
	dec_reg_base = mmHD0_VDEC0_VSI_BASE + offset;
	WREG32(dec_reg_base + mmVSI_DEC_SWREG1,
			FIELD_PREP(VSI_DEC_SWREG1_SW_DEC_E_M, 0x0) |
			FIELD_PREP(VSI_DEC_SWREG1_SW_DEC_ABORT_E_M, 0x1));

	/* Clear interrupts */
	WREG32(vcmd_reg_base + mmVSI_CMD_SWREG17,
			FIELD_PREP(VSI_CMD_SWREG17_SW_IRQ_ENDCMD_M, 0x1) |
			FIELD_PREP(VSI_CMD_SWREG17_SW_IRQ_BUSERR_M, 0x1) |
			FIELD_PREP(VSI_CMD_SWREG17_SW_IRQ_TIMEOUT_M, 0x1) |
			FIELD_PREP(VSI_CMD_SWREG17_SW_IRQ_CMDERR_M, 0x1) |
			FIELD_PREP(VSI_CMD_SWREG17_SW_IRQ_ABORT_M, 0x1) |
			FIELD_PREP(VSI_CMD_SWREG17_SW_IRQ_JMP_M, 0x1));

	brdg_ctrl_reg_base = mmHD0_VDEC0_BRDG_CTRL_BASE + offset;
	WREG32(brdg_ctrl_reg_base + mmVDEC_BRDG_CTRL_GRACEFUL,
			FIELD_PREP(VDEC_BRDG_CTRL_GRACEFUL_STOP_M, 0x1));

	timeout_usec = hdev->pldm ? GAUDI3_PLDM_VDEC_TIMEOUT_USEC : GAUDI3_VDEC_TIMEOUT_USEC;
	rc = hl_poll_timeout(
			hdev,
			brdg_ctrl_reg_base + mmVDEC_BRDG_CTRL_GRACEFUL,
			graceful,
			(graceful & VDEC_BRDG_CTRL_GRACEFUL_PEND_M),
			1000,
			timeout_usec);
	if (rc)
		dev_err(hdev->dev, "Failed to stop traffic from HD%d DEC%d\n", hdcore, inst);
}

void gaudi3_stop_decoder(struct hl_device *hdev)
{
	struct gaudi3_device *gaudi3 = hdev->asic_specific;
	struct iterate_module_ctx iter_ctx = {
		.fn = gaudi3_stop_decoder_engine
	};

	if (!(gaudi3->hw_cap_dec_initialized & HW_CAP_DEC_MASK))
		return;

	gaudi3_iterate_decoders(hdev, &iter_ctx);
}

static void gaudi3_set_arc_running_mode(struct hl_device *hdev, u32 cpu_id, u32 run_mode)
{
	u32 reg_base, offset, reg_val;

	reg_base = gaudi3_arc_blocks_bases[cpu_id];
	if (run_mode == HL_ENGINE_CORE_RUN) {
		reg_val = FIELD_PREP(QMAN_ARC_AUX_RUN_REQ_VAL_M, 1);
		offset = mmQMAN_ARC_AUX_RUN_REQ;
	} else {
		reg_val = FIELD_PREP(QMAN_ARC_AUX_HALT_REQ_VAL_M, 1);
		offset = mmQMAN_ARC_AUX_HALT_REQ;
	}

	WREG32(reg_base + offset, reg_val);
}

static int gaudi3_verify_arc_running_mode(struct hl_device *hdev, u32 cpu_id, u32 run_mode)
{
	int rc;
	u32 reg_base, val, ack_mask, req_val, offset, timeout_usec = 100000;

	if (hdev->pldm)
		timeout_usec *= 100;

	reg_base = gaudi3_arc_blocks_bases[cpu_id];
	if (run_mode == HL_ENGINE_CORE_RUN) {
		ack_mask = QMAN_ARC_AUX_RUN_HALT_ACK_RUN_ACK_M;
		offset = mmQMAN_ARC_AUX_RUN_REQ;
		req_val = FIELD_PREP(QMAN_ARC_AUX_RUN_REQ_VAL_M, 0);
	} else {
		ack_mask = QMAN_ARC_AUX_RUN_HALT_ACK_HALT_ACK_M;
		offset = mmQMAN_ARC_AUX_HALT_REQ;
		req_val = FIELD_PREP(QMAN_ARC_AUX_HALT_REQ_VAL_M, 0);
	}

	rc = hl_poll_timeout(hdev, reg_base + mmQMAN_ARC_AUX_RUN_HALT_ACK,
				val, ((val & ack_mask) == ack_mask),
				1000, timeout_usec);

	if (!rc)
		/* Clear */
		WREG32(reg_base + offset, req_val);

	return rc;
}

int gaudi3_set_engine_cores(struct hl_device *hdev, u32 *core_ids,
					u32 num_cores, u32 core_command)
{
	int i, rc;

	for (i = 0 ; i < num_cores ; i++) {
		if (gaudi3_is_arc_initialized(hdev, core_ids[i]))
			gaudi3_set_arc_running_mode(hdev, core_ids[i], core_command);
	}

	for (i = 0 ; i < num_cores ; i++) {
		if (gaudi3_is_arc_initialized(hdev, core_ids[i])) {
			rc = gaudi3_verify_arc_running_mode(hdev, core_ids[i], core_command);

			if (rc) {
				dev_err(hdev->dev, "failed to %s arc: %d\n",
					(core_command == HL_ENGINE_CORE_HALT) ?
					"HALT" : "RUN", core_ids[i]);
				return rc;
			}
		}
	}

	return 0;
}

static int gaudi3_set_engine_modes(struct hl_device *hdev, u32 *engine_ids,
					u32 num_engines, u32 engine_command)
{
	dev_err(hdev->dev, "setting engine_modes is currently not supported on Gaudi3\n");

	return -EPERM;
}

int gaudi3_set_engines(struct hl_device *hdev, u32 *engine_ids,
					u32 num_engines, u32 engine_command)
{
	switch (engine_command) {
	case HL_ENGINE_CORE_HALT:
	case HL_ENGINE_CORE_RUN:
		return gaudi3_set_engine_cores(hdev, engine_ids, num_engines, engine_command);

	case HL_ENGINE_STALL:
	case HL_ENGINE_RESUME:
		return gaudi3_set_engine_modes(hdev, engine_ids, num_engines, engine_command);

	default:
		dev_err(hdev->dev, "failed to execute command id %u\n", engine_command);
		return -EINVAL;
	}
}

static void gaudi3_verify_mstr_if_dbg_counters_func(struct hl_device *hdev,
					struct gaudi3_mstr_if_dbg_block_operation *operation)
{
	u32 hbw_otf_wr_cnt = 0, hbw_otf_rd_cnt = 0, lbw_otf_wr_cnt = 0, lbw_otf_rd_cnt = 0, addr;

	if (!operation->dbg_hbw_base_addr && !operation->dbg_lbw_base_addr)
		return;

	if (operation->dbg_hbw_base_addr) {
		hbw_otf_wr_cnt = RREG32(operation->dbg_hbw_base_addr +
					mmMSTR_IF_DBG_HBW_OTF_WR_TOTAL_CNT);
		hbw_otf_rd_cnt = RREG32(operation->dbg_hbw_base_addr +
					mmMSTR_IF_DBG_HBW_OTF_RD_TOTAL_CNT);
	}

	if (operation->dbg_lbw_base_addr) {
		lbw_otf_wr_cnt = RREG32(operation->dbg_lbw_base_addr +
					mmMSTR_IF_DBG_LBW_OTF_WR_TOTAL_CNT);
		lbw_otf_rd_cnt = RREG32(operation->dbg_lbw_base_addr +
					mmMSTR_IF_DBG_LBW_OTF_RD_TOTAL_CNT);
	}

	if (!hbw_otf_wr_cnt && !hbw_otf_rd_cnt && !lbw_otf_wr_cnt && !lbw_otf_rd_cnt)
		return;

	addr = operation->dbg_hbw_base_addr ?
			(operation->dbg_hbw_base_addr & ~(HL_BLOCK_SIZE - 1)) :
			(operation->dbg_lbw_base_addr & ~(HL_BLOCK_SIZE - 1));

	if (operation->dbg_hbw_base_addr && operation->dbg_lbw_base_addr)
		dev_err(hdev->dev,
			"active transactions in mstr_if %#x: hbw wr %u, hbw rd %u, lbw wr %u, lbw rd %u\n",
			addr, hbw_otf_wr_cnt, hbw_otf_rd_cnt, lbw_otf_wr_cnt, lbw_otf_rd_cnt);
	else if (operation->dbg_hbw_base_addr)
		dev_err(hdev->dev,
			"active transactions in mstr_if %#x: hbw wr %u, hbw rd %u\n",
			addr, hbw_otf_wr_cnt, hbw_otf_rd_cnt);
	else
		dev_err(hdev->dev,
			"active transactions in mstr_if %#x: lbw wr %u, lbw rd %u\n",
			addr, lbw_otf_wr_cnt, lbw_otf_rd_cnt);
}

static void gaudi3_verify_compute_mstr_if_dbg_counters(struct hl_device *hdev)
{
	struct gaudi3_mstr_if_dbg_block_operation operation = {
		.func = gaudi3_verify_mstr_if_dbg_counters_func,
	};

	gaudi3_iterate_compute_mstr_if_dbg_blocks(hdev, &operation);
}

static void gaudi3_verify_nic_mstr_if_dbg_counters(struct hl_device *hdev)
{
	struct gaudi3_mstr_if_dbg_block_operation operation = {
		.func = gaudi3_verify_mstr_if_dbg_counters_func,
	};

	gaudi3_iterate_nic_mstr_if_dbg_blocks(hdev, &operation);
}

static void gaudi3_halt_engines(struct hl_device *hdev, bool hard_reset, bool fw_reset)
{
	u32 wait_timeout_ms;

	gaudi3_halt_engines_fw_config(hdev);

	if (hdev->pldm)
		wait_timeout_ms = GAUDI3_PLDM_HALT_ENGINES_WAIT_MSEC;
	else
		wait_timeout_ms = GAUDI3_RESET_WAIT_MSEC;

	/*
	 * Mark the NIC as in reset to avoid any new NIC accesses to the HW. This must be done
	 * before we stop the CPU as the NIC might use it e.g. get/set EEPROM data.
	 */
	if (hard_reset)
		hl_cn_hard_reset_prepare(hdev);

	if (fw_reset)
		goto skip_engines;

	gaudi3_stop_edma_qmans(hdev);
	gaudi3_stop_tpc_qmans(hdev);
	gaudi3_stop_mme_qmans(hdev);
	gaudi3_stop_rotator_qmans(hdev);

	msleep(wait_timeout_ms);

	gaudi3_halt_arcs(hdev);
	gaudi3_halt_pdma(hdev);
	gaudi3_halt_dup(hdev);
	gaudi3_stall_edma(hdev);
	gaudi3_stall_tpc(hdev);
	gaudi3_stall_mme(hdev);
	gaudi3_stall_rotator(hdev);
	gaudi3_stop_decoder(hdev);

	msleep(wait_timeout_ms);

	gaudi3_disable_edma_qmans(hdev);
	gaudi3_disable_tpc_qmans(hdev);
	gaudi3_disable_mme_qmans(hdev);
	gaudi3_disable_rotator_qmans(hdev);

	gaudi3_disable_timestamp(hdev);

	/* Verify that there are no on-the-fly AXI transactions after halting the engines */
	gaudi3_verify_compute_mstr_if_dbg_counters(hdev);

	gaudi3_disable_interrupt_aggr_msgs(hdev);

skip_engines:
	if (hard_reset) {
		hl_cn_stop(hdev);
		gaudi3_verify_nic_mstr_if_dbg_counters(hdev);
		gaudi3_disable_msix(hdev);
		return;
	}

	gaudi3_sync_irqs(hdev);
	hl_cn_synchronize_irqs(hdev);
}

static int gaudi3_suspend(struct hl_device *hdev)
{
	int rc;

	rc = hl_fw_send_pci_access_msg(hdev, CPUCP_PACKET_DISABLE_PCI_ACCESS, 0x0);
	if (rc)
		dev_err(hdev->dev, "Failed to disable PCI access from CPU\n");

	return rc;
}

static int gaudi3_resume(struct hl_device *hdev)
{
	return gaudi3_init_iatu(hdev);
}

int gaudi3_mmap(struct hl_device *hdev, struct vm_area_struct *vma,
		void *cpu_addr, dma_addr_t dma_addr, size_t size)
{
	int rc;

	vm_flags_set(vma, VM_IO | VM_PFNMAP | VM_DONTEXPAND | VM_DONTDUMP |
			VM_DONTCOPY | VM_NORESERVE);

#ifdef _HAS_DMA_MMAP_COHERENT

	rc = dma_mmap_coherent(hdev->dev, vma, cpu_addr, dma_addr, size);
	if (rc)
		dev_err(hdev->dev, "dma_mmap_coherent error %d", rc);

#else

	rc = remap_pfn_range(vma, vma->vm_start,
				virt_to_phys(cpu_addr) >> PAGE_SHIFT,
				size, vma->vm_page_prot);
	if (rc)
		dev_err(hdev->dev, "remap_pfn_range error %d", rc);

#endif

	return rc;
}

void gaudi3_ring_doorbell(struct hl_device *hdev, u32 hw_queue_id, u32 pi)
{
	u32 db_reg_offset, db_value;

	db_reg_offset = mmD0_PARC_ARC1_CFG_BASE + mmARC_PF_PQ_PI;
	db_value = pi;

	/* Ring the doorbell */
	WREG32(db_reg_offset, db_value);

	/* Make sure device CPU will read latest data from host */
	mb();
	WREG32(mmD0_PARC_INT_GEN_BASE + mmINTR_GEN_MSG2WIRE_SW, 0);
}

void gaudi3_pqe_write(struct hl_device *hdev, __le64 *pqe, struct hl_bd *bd)
{
}

void *gaudi3_dma_alloc_coherent(struct hl_device *hdev, size_t size,
				dma_addr_t *dma_handle, gfp_t flags)
{
	return dma_alloc_coherent(&hdev->pdev->dev, size, dma_handle, flags);
}

void gaudi3_dma_free_coherent(struct hl_device *hdev, size_t size,
				void *cpu_addr, dma_addr_t dma_handle)
{
	dma_free_coherent(&hdev->pdev->dev, size, cpu_addr, dma_handle);
}

static int gaudi3_kernel_ctx_unmap_addr(struct hl_device *hdev, u64 virt_addr, int size,
						bool is_dram)
{
	u32 flags = is_dram ? VM_TYPE_PHYS_PACK : VM_TYPE_USERPTR;
	int rc;

	mutex_lock(&hdev->mmu_lock);

	rc = hl_mmu_unmap_contiguous(hdev->kernel_ctx, virt_addr, size);
	rc |= hl_mmu_invalidate_cache_range(hdev, false, flags, hdev->kernel_ctx->asid, virt_addr,
						size);

	mutex_unlock(&hdev->mmu_lock);

	rc |= hl_unreserve_va_block(hdev, hdev->kernel_ctx, virt_addr, size);
	if (rc)
		dev_err(hdev->dev, "failed to unreserve va 0x%llx\n", virt_addr);

	return rc;
}

static int gaudi3_kernel_ctx_map_addr(struct hl_device *hdev, u64 phys_addr, u64 *virt_addr,
						int size, bool is_dram)
{
	enum hl_va_range_type range;
	u32 flags;
	u64 va;
	int rc;

	if (is_dram) {
		range = HL_VA_RANGE_TYPE_DRAM;
		flags = VM_TYPE_PHYS_PACK;
	} else {
		range = HL_VA_RANGE_TYPE_HOST;
		flags = VM_TYPE_USERPTR;
	}
	*virt_addr = 0;
	va = hl_reserve_va_block(hdev, hdev->kernel_ctx, range, size,
				HL_MMU_VA_ALIGNMENT_NOT_NEEDED);
	if (!va)
		return -ENOMEM;

	mutex_lock(&hdev->mmu_lock);

	rc = hl_mmu_map_contiguous(hdev->kernel_ctx, va, phys_addr, size);
	if (rc) {
		mutex_unlock(&hdev->mmu_lock);
		dev_err(hdev->dev, "Failed to create mapping in kernel\n");
		goto err_unreserve_va;
	}

	rc = hl_mmu_invalidate_cache_range(hdev, false, flags, hdev->kernel_ctx->asid, va, size);
	if (rc)
		goto err_mmu_unmap;

	mutex_unlock(&hdev->mmu_lock);

	*virt_addr = va;

	return 0;

err_mmu_unmap:
	hl_mmu_unmap_contiguous(hdev->kernel_ctx, va, size);
	mutex_unlock(&hdev->mmu_lock);
err_unreserve_va:
	if (hl_unreserve_va_block(hdev, hdev->kernel_ctx, va, size))
		dev_err(hdev->dev, "failed to unreserve va 0x%llx in failure flow\n", va);

	return rc;
}

static u32 gaudi3_err_cause_iterator(struct hl_device *hdev, u32 err_msk,
					const char * const *err_tbl, char *initiator, char *type)
{
	u32 err_idx = 0, err_cnt = 0;

	while (err_msk) {
		if (err_msk & 1) {
			dev_err_ratelimited(hdev->dev, "%s %s error: %s\n",
					initiator, type, err_tbl[err_idx]);
			err_cnt++;
		}
		err_idx++;
		err_msk >>= 1;
	}

	return err_cnt;
}

static u32 gaudi3_handle_err_cause_reg(struct hl_device *hdev, u64 err_cause_reg, bool clear_err,
					const char * const *err_tbl, char *initiator, char *type,
					u32 err_ignore_msk)
{
	u32 err_cause_val = RREG32(err_cause_reg) & (~err_ignore_msk), err_cnt = 0;

	if (!err_cause_val)
		return 0;

	err_cnt = gaudi3_err_cause_iterator(hdev, err_cause_val, err_tbl, initiator, type);

	if (clear_err)
		WREG32(err_cause_reg, err_cause_val);

	return err_cnt;
}

static void gaudi3_pdma_print_ch_sei_err(struct hl_device *hdev, u32 ch_idx)
{
	u64 err_cause_reg_offset, ch_err_cause_addr, ch_err_ignore_mask;
	u32 ch_base_addr = gaudi3_pdma_get_ch_reg_base(hdev, ch_idx);
	struct asic_fixed_properties *prop = &hdev->asic_prop;
	u32 grp_idx = ch_idx / prop->pdma_grp_ch_max,
		ch_idx_in_grp = ch_idx % prop->pdma_grp_ch_max;
	char pdma_channel_name[SZ_128];

	err_cause_reg_offset = PDMA_CH_B_OFFSET + mmPDMA_CH_B_ERR_STATUS;
	ch_err_ignore_mask = PDMA_CH_B_ERR_STATUS_VALID_M; /* Ignore valid bit */
	ch_err_cause_addr = ch_base_addr + err_cause_reg_offset;
	snprintf(pdma_channel_name, sizeof(pdma_channel_name) - 1,
			"PDMA group=%u, PDMA channel (in group)=%u", grp_idx, ch_idx_in_grp);

	gaudi3_handle_err_cause_reg(hdev, ch_err_cause_addr, false,
			gaudi3_pdma_sei_err_cause, pdma_channel_name, "SEI",
			ch_err_ignore_mask);
}

static void gaudi3_pdma_print_ch_status(struct hl_device *hdev, u32 ch_idx)
{
	u32 str_size = 0, read_val, ch_addr = gaudi3_pdma_get_ch_reg_base(hdev, ch_idx);
	char debug_str[SZ_256];
	u16 max_size = SZ_256;
	u64 reg_addr;

	str_size += snprintf(debug_str + str_size, max_size - str_size,
			"PDMA channel %u debug info:\n", ch_idx);

	/* Channel status */
	reg_addr = ch_addr + PDMA_CH_B_OFFSET + mmPDMA_CH_B_STS;
	read_val = RREG32(reg_addr);

	str_size += snprintf(debug_str + str_size, max_size - str_size,
			"[CH_B_STS] is_busy=%u, is_halted=%u\n",
			FIELD_GET(PDMA_CH_B_STS_IS_BUSY_M, read_val),
			FIELD_GET(PDMA_CH_B_STS_IS_HALT_M, read_val));

	/* Channel debug information */
	reg_addr = ch_addr + PDMA_CH_B_OFFSET + mmPDMA_CH_B_DBG_STS;
	read_val = RREG32(reg_addr);
	str_size += snprintf(debug_str + str_size, max_size - str_size,
			"[CH_B_DBG_STS] channel dbg info: 0x%X (default=0x929)\n", read_val);

	dev_dbg(hdev->dev, "%s", debug_str);
}

static void gaudi3_pdma_print_grp_status(struct hl_device *hdev, u32 ch_idx)
{
	struct asic_fixed_properties *prop = &hdev->asic_prop;
	u32 read_val, str_size = 0, grp_idx = ch_idx / prop->pdma_grp_ch_max,
			grp_addr = gaudi3_pdma_grp_blocks_bases[grp_idx];
	char debug_str[3 * SZ_256];
	u16 max_size = 3 * SZ_256;
	u64 reg_addr;
	int i;

	str_size += snprintf(debug_str + str_size, max_size - str_size,
			"PDMA group %u debug info:\n", grp_idx);

	/* Free counter of read contexts handled */
	reg_addr = grp_addr + PDMA_CMN_B_OFFSET + mmPDMA_CMN_B_DBG_DESC_CNT;
	read_val = RREG32(reg_addr);
	str_size += snprintf(debug_str + str_size, max_size - str_size,
			"[CMN_B_DBG_DESC_CNT] cyclic read desc cnt: %u\n",
			read_val);

	/* DMA-status. 'Idle' when:
	 * 1. ~(hbw_rd_sts_busy | hbw_wr_sts_busy | ~data_pipe_empty)
	 * 2. instage descriptor q empty
	 * 3. wr comp fifo empty
	 */
	reg_addr = grp_addr + PDMA_CMN_B_OFFSET + mmPDMA_CMN_B_DMA_STATUS;
	read_val = RREG32(reg_addr);
	str_size += snprintf(debug_str + str_size, max_size - str_size,
			"[CMN_B_DMA_STATUS] DMA sts (6 ch bitmap): HALT: 0x%X, and BUSY: 0x%X\n",
			FIELD_GET(PDMA_CMN_B_DMA_STATUS_HALT_M, read_val),
			FIELD_GET(PDMA_CMN_B_DMA_STATUS_IDLE_M, read_val));

	if (!hdev->security_enable && !hdev->priv_security_enable) {
		for (i = 0 ; i < prop->pdma_grp_ch_max ; ++i) {
			reg_addr = grp_addr + PDMA_CMN_B_OFFSET +
					(mmPDMA_CMN_B_CH_DESC_CREDITS_0 + sizeof(u32) * i);
			read_val = RREG32(reg_addr);
			str_size += snprintf(debug_str + str_size, max_size - str_size,
					"[CMN_B_CH_DESC_CREDITS_%d] ch %d, credits num: %u\n",
					i, i, read_val);
		}
	}

	/* Common debug information */
	reg_addr = grp_addr + PDMA_CMN_B_OFFSET + mmPDMA_CMN_B_DBG_STS;
	read_val = RREG32(reg_addr);
	str_size += snprintf(debug_str + str_size, max_size - str_size,
			"[CMN_B_DBG_STS] grp dbg info: 0x%X (default=0x3E)\n", read_val);

	/* hbw sb rd and wbc wr inflight num */
	reg_addr = grp_addr + PDMA_CMN_B_OFFSET + mmPDMA_CMN_B_HBW_INFLIGHTS_STS;
	read_val = RREG32(reg_addr);
	str_size += snprintf(debug_str + str_size, max_size - str_size,
			"[CMN_B_HBW_INFLIGHTS_STS] open read buffer req cnt: %u, AXI inflight writes cnt: %u\n",
			FIELD_GET(PDMA_CMN_B_HBW_INFLIGHTS_STS_RSB_RD_M, read_val),
			FIELD_GET(PDMA_CMN_B_HBW_INFLIGHTS_STS_WBC_WR_M, read_val));

	/* lbw sb rd and wbc wr inflight num */
	reg_addr = grp_addr + PDMA_CMN_B_OFFSET + mmPDMA_CMN_B_LBW_INFLIGHTS_STS;
	read_val = RREG32(reg_addr);
	str_size += snprintf(debug_str + str_size, max_size - str_size,
			"[CMN_B_LBW_INFLIGHTS_STS] open read buffer req cnt: %u, AXI inflight writes cnt: %u\n",
			FIELD_GET(PDMA_CMN_B_LBW_INFLIGHTS_STS_RSB_RD_M, read_val),
			FIELD_GET(PDMA_CMN_B_LBW_INFLIGHTS_STS_WBC_WR_M, read_val));

	/* BUSY and counters */
	reg_addr = grp_addr + PDMA_CMN_B_OFFSET + mmPDMA_CMN_B_STS0;
	read_val = RREG32(reg_addr);
	str_size += snprintf(debug_str + str_size, max_size - str_size,
			"[CMN_B_STS0] read req cnt: %u, write req cnt (excluding comp msg): %u\n",
			FIELD_GET(PDMA_CMN_B_STS0_RD_REQ_CNT_M, read_val),
			FIELD_GET(PDMA_CMN_B_STS0_WR_REQ_CNT_M, read_val));

	dev_dbg(hdev->dev, "%s", debug_str);
}

void gaudi3_pdma_print_debug_info(struct hl_device *hdev, u32 ch_idx)
{
	gaudi3_pdma_print_ch_sei_err(hdev, ch_idx);
	gaudi3_pdma_print_ch_status(hdev, ch_idx);
	gaudi3_pdma_print_grp_status(hdev, ch_idx);
}

static void gaudi3_pdma_print_debug_info_all_ch(struct hl_device *hdev)
{
	struct gaudi3_device *gaudi3 = hdev->asic_specific;
	int i;

	for (i = 0 ; i < hdev->asic_prop.pdma_ch_max ; i++) {
		if (!(gaudi3->hw_cap_pdma_initialized & BIT(i)))
			continue;

		gaudi3_pdma_print_debug_info(hdev, i);
	}
}

static void gaudi3_split_job_between_all_pdma_channels(struct hl_device *hdev, void *data)
{
	struct gaudi3_pdma_job_params curr_job;
	struct gaudi3_pdma_job_params *job_params = data;
	struct gaudi3_device *gaudi3 = hdev->asic_specific;
	u8 num_of_pdma = hweight_long(gaudi3->hw_cap_pdma_initialized);
	int i;

	memset(&curr_job, 0, sizeof(struct gaudi3_pdma_job_params));
	/* ignore remainder */
	curr_job.size = job_params->size / num_of_pdma;
	curr_job.is_memset = job_params->is_memset;

	for (i = 0 ; i < hdev->asic_prop.pdma_ch_max ; i++) {
		if (!(gaudi3->hw_cap_pdma_initialized & BIT(i)))
			continue;

		curr_job.src = job_params->is_memset ? job_params->src :
					(job_params->src + (curr_job.size * i));
		curr_job.dst = job_params->dst + (curr_job.size * i);
		curr_job.ch_idx = i;
		curr_job.ch_reg_base = gaudi3_pdma_get_ch_reg_base(hdev, i);
		gaudi3_send_job_to_pdma(hdev, &curr_job);
	}
}

static void gaudi3_trigger_all_pdma_channels(struct hl_device *hdev,
					     struct gaudi3_pdma_job_params *job_params,
					     struct gaudi3_cq_mode_params *cq_params)
{
	struct gaudi3_device *gaudi3 = hdev->asic_specific;
	u8 num_of_pdma = hweight_long(gaudi3->hw_cap_pdma_initialized);

	cq_params->job_data = job_params;
	cq_params->job_str = job_params->job_str;
	cq_params->job = gaudi3_split_job_between_all_pdma_channels;
	cq_params->sob_id = GAUDI3_RESERVED_SOB_PDMA;
	cq_params->mon_id = GAUDI3_RESERVED_MON_PDMA;
	cq_params->cq_id = GAUDI3_RESERVED_CQ_PDMA;
	cq_params->target_sob_value = num_of_pdma;
	cq_params->timeout_usec = (hdev->pldm) ?
				(((job_params->size / SZ_1M) + 1) * GAUDI3_PDMA_TIMEOUT_USEC) :
				GAUDI3_PDMA_TIMEOUT_USEC;

	gaudi3_trigger_job(hdev, cq_params);
}

static int gaudi3_scrub_device_memory(struct hl_device *hdev,
				      const struct gaudi3_test_pdma_params *test_params,
				      int ch_idx)
{
	u64 device_addr, device_data = 0;
	int i, rc;

	device_addr = test_params->device_phys_addr + ch_idx * test_params->channel_transfer_size;

	/* Scrub device memory before DMAing to it */
	for (i = 0 ; i < test_params->channel_transfer_size ; i += sizeof(u32)) {

		rc = hdev->asic_funcs->access_dev_mem(hdev, test_params->region_type,
						      device_addr + i, &device_data,
						      DEBUGFS_WRITE32);

		device_data += 0x11111111;

		if (rc) {
			dev_crit(hdev->dev, "Failed to writel to dev_mem type %d, addr 0x%llx\n",
				 test_params->region_type, device_addr + i);
			return rc;
		}
	}

	return 0;
}

static int gaudi3_test_pdma_job_init(struct hl_device *hdev,
				     struct gaudi3_test_pdma_params *test_params)
{
	struct asic_fixed_properties *prop = &hdev->asic_prop;
	struct gaudi3_device *gaudi3 = hdev->asic_specific;
	u32 val, ch_reg_base;
	int rc, ch_idx, offset;
	bool is_dram_test;

	test_params->num_active_channels = hweight_long(gaudi3->hw_cap_pdma_initialized);
	test_params->channel_transfer_size = SZ_128;
	test_params->transfer_size = SZ_128 * hdev->asic_prop.pdma_ch_max;

	/* Either DRAM or SRAM is enabled */
	is_dram_test = !!hdev->cache_enable;


	if (is_dram_test) {
		test_params->region_type = PCI_REGION_DRAM;
		test_params->device_phys_addr = prop->dram_user_base_address;
		rc = gaudi3_kernel_ctx_map_addr(hdev, prop->dram_user_base_address,
						&test_params->device_va,
						test_params->transfer_size, true);
		if (rc)
			return rc;
	} else {
		test_params->region_type = PCI_REGION_SRAM;
		test_params->device_phys_addr = prop->sram_user_base_address;
		test_params->device_va = prop->sram_user_base_address;
	}

	test_params->host_ptr = hl_asic_dma_alloc_coherent(hdev,
							   test_params->transfer_size,
							   &test_params->host_mem_dma_addr,
							   GFP_KERNEL);
	if (!test_params->host_ptr) {
		rc = -ENOMEM;
		goto kernel_unmap_dev;
	}

	rc = gaudi3_kernel_ctx_map_addr(hdev, test_params->host_mem_dma_addr,
					&test_params->host_va, test_params->transfer_size, false);
	if (rc)
		goto free_host;

	for (ch_idx = 0 ; ch_idx < hdev->asic_prop.pdma_ch_max ; ch_idx++) {
		if (!(gaudi3->hw_cap_pdma_initialized & BIT(ch_idx)))
			continue;

		/* Prepare src data */
		offset = ch_idx * SZ_128 / sizeof(u32);
		val = GAUDI3_PDMA_TEST_VAL | ch_idx;
		memset32(&test_params->host_ptr[offset], val, SZ_128 / sizeof(u32));

		if (hdev->pldm) {
			rc = gaudi3_scrub_device_memory(hdev, test_params, ch_idx);
			/* Don't bother reverting HW cfg, the device is not usable if we fail */
			if (rc)
				goto mmu_unmap_host;
		}

		ch_reg_base = gaudi3_pdma_get_ch_reg_base(hdev, ch_idx);

		/* While testing we change to PDMA non bypass mode so we test the pmmu on the way */
		gaudi3_config_pdma_ch_mmu_mode(hdev, ch_reg_base, false, HL_KERNEL_ASID_ID);

		/* Set channel to be secured, as completion will be using a secured CQ */
		if (hdev->asic_prop.pdma_user_owned_ch_mask & BIT(ch_idx))
			gaudi3_config_pdma_ch_protection(hdev, ch_reg_base, true);
	}

	return 0;

mmu_unmap_host:
	gaudi3_kernel_ctx_unmap_addr(hdev, test_params->host_va,
				     test_params->transfer_size, false);
free_host:
	hl_asic_dma_free_coherent(hdev, test_params->transfer_size,
				  test_params->host_ptr, test_params->host_mem_dma_addr);
kernel_unmap_dev:
	if (is_dram_test)
		gaudi3_kernel_ctx_unmap_addr(hdev, test_params->device_va,
					     test_params->transfer_size, true);

	return rc;
}

static int gaudi3_test_pdma_job_fini(struct hl_device *hdev,
				      struct gaudi3_test_pdma_params *test_params)
{
	struct asic_fixed_properties *prop = &hdev->asic_prop;
	struct gaudi3_device *gaudi3 = hdev->asic_specific;
	u32 ch_reg_base;
	int ch_idx, rc, ret = 0;

	for (ch_idx = 0 ; ch_idx < hdev->asic_prop.pdma_ch_max ; ch_idx++) {
		if (!(gaudi3->hw_cap_pdma_initialized & BIT(ch_idx)))
			continue;

		ch_reg_base = gaudi3_pdma_get_ch_reg_base(hdev, ch_idx);

		/* Restore channel's prior security level and bypass mode */
		if (prop->pdma_user_owned_ch_mask & BIT(ch_idx)) {
			gaudi3_config_pdma_ch_protection(hdev, ch_reg_base, false);
			gaudi3_config_pdma_ch_mmu_mode(hdev, ch_reg_base, false, HL_KERNEL_ASID_ID);
		} else {
			gaudi3_config_pdma_ch_protection(hdev, ch_reg_base, true);
			gaudi3_config_pdma_ch_mmu_mode(hdev, ch_reg_base, true, HL_KERNEL_ASID_ID);
		}
	}

	rc = gaudi3_kernel_ctx_unmap_addr(hdev, test_params->host_va,
					  test_params->transfer_size, false);
	hl_asic_dma_free_coherent(hdev, test_params->transfer_size,
				  test_params->host_ptr, test_params->host_mem_dma_addr);
	if (test_params->region_type == PCI_REGION_DRAM) {
		ret = gaudi3_kernel_ctx_unmap_addr(hdev, test_params->device_va,
						   test_params->transfer_size, true);
	}

	return rc ? rc : ret;
}

static int gaudi3_test_pdma_verify_result(struct hl_device *hdev,
					  struct gaudi3_test_pdma_params *test_params)
{
	struct gaudi3_device *gaudi3 = hdev->asic_specific;
	u64 device_addr, device_data;
	u32 val;
	uint i, ch_idx, offset;
	int rc = 0;

	for (ch_idx = 0 ; ch_idx < hdev->asic_prop.pdma_ch_max ; ch_idx++) {
		if (!(gaudi3->hw_cap_pdma_initialized & BIT(ch_idx)))
			continue;

		offset = ch_idx * test_params->channel_transfer_size / sizeof(u32);
		val = GAUDI3_PDMA_TEST_VAL | ch_idx;

		for (i = 0 ; i < test_params->channel_transfer_size / sizeof(u32) ; i++) {
			if (test_params->host_ptr[offset + i] == val)
				continue;

			/* We should avoid any error in case simulator is already going down */
			if (hdev->simulator_crashed)
				return 0;

			dev_err(hdev->dev,
				"PDMA ch %u test Device <--> Host, data validation failed",
				ch_idx);

			if (hdev->pldm) {
				device_addr = test_params->device_phys_addr +
							(offset + i) * sizeof(u32);

				rc = hdev->asic_funcs->access_dev_mem(hdev,
								test_params->region_type,
								device_addr, &device_data,
								DEBUGFS_READ32);
				if (rc)
					dev_crit(hdev->dev,
						 "Failed to readl from dev_mem type %d, addr 0x%llx\n",
						 test_params->region_type, device_addr);

				dev_err(hdev->dev, "src: %8x, data: %8x, dst: %8x region: %s",
					val, (u32)device_data, test_params->host_ptr[offset + i],
					(test_params->region_type == PCI_REGION_DRAM) ?
										"DRAM":"SRAM");
			} else {
				dev_err(hdev->dev, "src: %8x, dst: %8x region: %s",
					val, test_params->host_ptr[offset + i],
					(test_params->region_type == PCI_REGION_DRAM) ?
										"DRAM":"SRAM");
			}

			/* if host_mem_va is not as expected, it means dma failed, set rc = -EIO */
			rc = -EIO;
		}
	}

	return rc;
}

static void gaudi3_test_pdma_clear_ctrl_regs(struct hl_device *hdev)
{
	struct gaudi3_device *gaudi3 = hdev->asic_specific;
	u32 ch_reg_base;
	int ch_idx;

	for (ch_idx = 0 ; ch_idx < hdev->asic_prop.pdma_ch_max ; ch_idx++) {
		if (!(gaudi3->hw_cap_pdma_initialized & BIT(ch_idx)))
			continue;

		/* Make sure to clear the ctrl register for the future use */
		ch_reg_base = gaudi3_pdma_get_ch_reg_base(hdev, ch_idx);
		WREG32(ch_reg_base + PDMA_CH_A_CTX_OFFSET + mmPDMA_CH_A_CTX_CTRL_MAIN, 0);
	}
}

static int gaudi3_test_pdma_access(struct hl_device *hdev)
{
	struct gaudi3_test_pdma_params test_params = {};
	struct gaudi3_pdma_job_params job_params = {};
	struct gaudi3_cq_mode_params cq_params = {};
	struct gaudi3_device *gaudi3 = hdev->asic_specific;
	int rc, ret;
	bool is_dram_test = !!hdev->cache_enable;

	/* No PDMA channel is initialized */
	if (!gaudi3->hw_cap_pdma_initialized)
		return 0;

	/* Neither DRAM nor SRAM is available for PDMA testing */
	if (hdev->cache_enable && !hdev->dram_enable)
		return 0;

	rc = gaudi3_test_pdma_job_init(hdev, &test_params);
	if (rc)
		return rc;

	/* prepare JOB params */
	job_params.src = test_params.host_va;
	job_params.dst = test_params.device_va;
	job_params.size = test_params.transfer_size;
	job_params.is_memset = false;
	snprintf(job_params.job_str, HL_STR_MAX,
		 "PDMA %u Channels Host --> %s",
		 test_params.num_active_channels,
		 (test_params.region_type == PCI_REGION_DRAM) ? "DRAM" : "SRAM");

	gaudi3_trigger_all_pdma_channels(hdev, &job_params, &cq_params);
	rc =  gaudi3_wait_for_cq_completion(hdev, &cq_params);
	gaudi3_test_pdma_clear_ctrl_regs(hdev);
	if (rc) {
		dev_err(hdev->dev,
			"PDMA test Device <--> Host, did not complete in time (rc = %d)\n", rc);
		goto exit;
	}

	/* Clean the host buf before receiving the data back */
	memset32(test_params.host_ptr, 0, test_params.transfer_size / sizeof(u32));

	/* update JOB params and get the data back */
	job_params.src = test_params.device_va;
	job_params.dst = test_params.host_va;
	snprintf(job_params.job_str, HL_STR_MAX,
		 "PDMA %u Channels %s --> Host",
		 test_params.num_active_channels, is_dram_test ? "DRAM" : "SRAM");

	gaudi3_trigger_all_pdma_channels(hdev, &job_params, &cq_params);
	rc =  gaudi3_wait_for_cq_completion(hdev, &cq_params);
	gaudi3_test_pdma_clear_ctrl_regs(hdev);
	if (rc)
		goto exit;

	rc = gaudi3_test_pdma_verify_result(hdev, &test_params);
	if (rc)
		goto exit;

	/* clear device memory */
	job_params.src = 0;
	job_params.dst = test_params.device_va;
	job_params.is_memset = true;
	snprintf(job_params.job_str, HL_STR_MAX,
		 "PDMA %u Channels clearing %s test area\n",
		 test_params.num_active_channels, is_dram_test ? "DRAM" : "SRAM");

	gaudi3_trigger_all_pdma_channels(hdev, &job_params, &cq_params);
	rc =  gaudi3_wait_for_cq_completion(hdev, &cq_params);
	gaudi3_test_pdma_clear_ctrl_regs(hdev);

exit:
	if (rc)
		gaudi3_pdma_print_debug_info_all_ch(hdev);
	ret = gaudi3_test_pdma_job_fini(hdev, &test_params);
	return rc ? rc : ret;
}

static int gaudi3_test_kdma_access(struct hl_device *hdev)
{
	struct asic_fixed_properties *prop = &hdev->asic_prop;
	struct gaudi3_device *gaudi3 = hdev->asic_specific;
	struct gaudi3_pdma_job_params job_params = {};
	u32 *host_mem_virtual_addr, val = 0x3dea;
	int i, rc, ret_val = 0, num_regs = 4;
	u64 regs_address, regs_dma_address;
	dma_addr_t host_mem_dma_addr;

	if ((prop->pdma_user_owned_ch_mask & BIT(KDMA_CH_ID)) ||
			!(gaudi3->hw_cap_pdma_initialized & BIT(KDMA_CH_ID)))
		return 0;

	/* Setup host memory for the test */
	host_mem_virtual_addr = hl_asic_dma_alloc_coherent(hdev, num_regs * sizeof(u32),
								&host_mem_dma_addr, GFP_KERNEL);

	if (!host_mem_virtual_addr)
		return -ENOMEM;

	/* Get registers that are safe to manipulate for the test */
	regs_address = mmHD0_SYNC_MNGR_OBJS_BASE + mmSOB_OBJS_SOB_OBJ_0_0 +
			prop->first_available_user_sob[0] * 4;
	regs_dma_address = CFG_BAR_BASE + regs_address;

	/* Prepare data */
	for (i = 0 ; i < num_regs ; i++) {
		host_mem_virtual_addr[i] = val;
		WREG32(regs_address + i * sizeof(u32), 0);
	}

	/* Flush writes */
	RREG32(regs_address);

	/* prepare JOB params */

	/* KDMA is the 1st channel in the 1st PDMA group */
	job_params.ch_idx = KDMA_CH_ID;
	job_params.ch_reg_base = gaudi3_pdma_get_ch_reg_base(hdev, KDMA_CH_ID);
	job_params.src = host_mem_dma_addr;
	job_params.dst = regs_dma_address;
	job_params.size = num_regs * sizeof(u32);
	job_params.is_memset = false;
	snprintf(job_params.job_str, HL_STR_MAX, "KDMA Host->Registers");

	/* Host -> Regs */
	rc = gaudi3_trigger_pdma_job_and_wait_for_cq_completion(hdev, &job_params);
	if (rc) {
		ret_val = rc;
		goto free_mem;
	} else {
		/* Verify data had been DMAed */
		for (i = 0 ; i < num_regs * sizeof(u32) ; i += sizeof(u32)) {
			if (RREG32(regs_address + i) != val) {
				dev_err(hdev->dev,
					"KDMA Host->Registers test, data validation failed\n");
				ret_val = -EIO;
				break;
			}
		}
	}

	for (i = 0 ; i < num_regs ; i++) {
		host_mem_virtual_addr[i] = 0;
		WREG32(regs_address + i * sizeof(u32), val);
	}
	/* Flush writes */
	RREG32(regs_address);

	/* update JOB params */
	job_params.src = regs_dma_address;
	job_params.dst = host_mem_dma_addr;
	snprintf(job_params.job_str, HL_STR_MAX, "KDMA Registers->Host");

	/* Regs -> HOST */
	rc = gaudi3_trigger_pdma_job_and_wait_for_cq_completion(hdev, &job_params);
	if (rc) {
		ret_val = rc;
	} else {
		for (i = 0 ; i < num_regs ; i++) {
			if (host_mem_virtual_addr[i] != val) {
				dev_err(hdev->dev,
					"KDMA test Registers->Host, data validation failed\n");
				ret_val = -EIO;
				break;
			}
		}
	}

	/* Zero the regs after usage */
	for (i = 0 ; i < num_regs ; i++)
		WREG32(regs_address + i * sizeof(u32), 0);

	/* Flush writes */
	RREG32(regs_address);

free_mem:
	/* Free memory */
	hl_asic_dma_free_coherent(hdev, num_regs * sizeof(u32), host_mem_virtual_addr,
					host_mem_dma_addr);

	if (hdev->simulator_crashed)
		return 0;

	return ret_val;
}

static int gaudi3_test_qman_wait_completion(struct hl_device *hdev, u32 engine_id,
					    const char *test_name, u32 sob_addr, u32 sob_val)
{
	u32 tmp, timeout_usec = GAUDI3_QMAN_TEST_WAIT_USEC;
	int rc;

	if (hdev->pldm)
		timeout_usec = GAUDI3_PLDM_QMAN_TEST_WAIT_USEC;

	rc = hl_poll_timeout(hdev, sob_addr, tmp, (tmp == sob_val),
					HL_POLL_SLEEP_US, timeout_usec);
	if (rc == -ETIMEDOUT) {
		dev_err(hdev->dev, "%s test for engine %d failed\n", test_name, engine_id);
		rc = -EIO;
	}

	return rc;
}

static void gaudi3_qman_set_test_mode(struct hl_device *hdev, u32 engine_id, bool enable)
{
	u32 qm_reg_base = gaudi3_qm_blocks_bases[engine_id];

	gaudi3_axuser_hbw_mmu_bp_set(hdev, qm_reg_base + QM_AXUSER_HBW_BASE_OFFSET, enable);
}

static void gaudi3_test_qman_send_msg(struct hl_device *hdev, u32 engine_id,
				      dma_addr_t pkt_dma_addr, size_t pkt_size)
{
	u32 qm_reg_base = gaudi3_qm_blocks_bases[engine_id];

	/* QMAN CQF */
	WREG32(qm_reg_base + mmQMAN_CQ_PTR_LO, lower_32_bits(pkt_dma_addr));
	WREG32(qm_reg_base + mmQMAN_CQ_PTR_HI, upper_32_bits(pkt_dma_addr));
	WREG32(qm_reg_base + mmQMAN_CQ_TSIZE, pkt_size);
	WREG32(qm_reg_base + mmQMAN_CQ_CTL, 0);
}

static void gaudi3_test_qman_arc_send_msg(struct hl_device *hdev, u32 engine_id,
					  dma_addr_t pkt_dma_addr, size_t pkt_size)
{
	u32 qm_reg_base = gaudi3_qm_blocks_bases[engine_id];

	/* QMAN ARC_CQF */
	WREG32(qm_reg_base + mmQMAN_ARC_CQ_PTR_LO, lower_32_bits(pkt_dma_addr));
	WREG32(qm_reg_base + mmQMAN_ARC_CQ_PTR_HI, upper_32_bits(pkt_dma_addr));
	WREG32(qm_reg_base + mmQMAN_ARC_CQ_TSIZE, pkt_size);
	WREG32(qm_reg_base + mmQMAN_ARC_CQ_CTL, 0);
}

static int gaudi3_test_qmans_get_sob_for_engine(struct hl_device *hdev,
						enum gaudi3_engine_id engine_id,
						struct gaudi3_sob_info *sob)
{
	if (engine_id >= GAUDI3_ENGINE_ID_SIZE)
		return -EINVAL;

	sob->offset = (hdev->asic_prop.first_available_user_sob[0] + engine_id) * sizeof(u32);
	sob->addr = mmHD0_SYNC_MNGR_OBJS_BASE + mmSOB_OBJS_SOB_OBJ_0_0 + sob->offset;
	sob->base = 1;	/* QMAN CP message base for SOB */
	sob->val = 0x5a5a;

	return 0;
}

static int gaudi3_test_qmans_kdma_and_cpu(struct hl_device *hdev)
{
	struct gaudi3_device *gaudi3 = hdev->asic_specific;
	struct gaudi3_qmans_test_info *msg_info = gaudi3->qmans_test_info;
	struct packet_msg_short *msg_short_pkt;
	struct gaudi3_sob_info *sob;
	dma_addr_t pkt_dma_addr;
	size_t pkt_size = sizeof(struct packet_msg_short);
	u32 ctl;
	int rc = 0, i, j;

	/* send messages on all QMANs */
	for (i = GAUDI3_HDCORE1_ENGINE_ID_EDMA_0 ; i <= GAUDI3_HDCORE6_ENGINE_ID_ROT_1 ; i++) {
		if (!gaudi3_is_engine_enabled(hdev, i))
			continue;

		j = i - GAUDI3_HDCORE1_ENGINE_ID_EDMA_0;
		msg_short_pkt = msg_info[j].kern_addr;
		pkt_dma_addr = msg_info[j].dma_addr;
		sob = &msg_info[j].sob;

		/* fill msg info */
		ctl = FIELD_PREP(GAUDI3_PKT_CTL_OPCODE_MASK, PACKET_MSG_SHORT) |
			FIELD_PREP(GAUDI3_PKT_CTL_EB_MASK, 0x1) |
			FIELD_PREP(GAUDI3_PKT_CTL_SWITCH_MASK, 0x1) |
			FIELD_PREP(GAUDI3_PKT_CTL_MB_MASK, 0x1) |
			FIELD_PREP(GAUDI3_PKT_MSG_SHORT_CTL_BASE_LSB_MASK, sob->base) |
			FIELD_PREP(GAUDI3_PKT_MSG_SHORT_CTL_ADDR_OFFSET_MASK, sob->offset);

		msg_short_pkt->value = cpu_to_le32(sob->val);
		msg_short_pkt->ctl = cpu_to_le32(ctl);

		gaudi3_qman_set_test_mode(hdev, i, true);
		/* Reset the SOB value */
		WREG32(sob->addr, 0);

		gaudi3_test_qman_send_msg(hdev, i, pkt_dma_addr, pkt_size);
	}

	/* test the KDMA while QMANs are working */
	rc = gaudi3_test_kdma_access(hdev);
	if (rc)
		return rc;

	/* wait for QMANs completion */
	for (i = GAUDI3_HDCORE1_ENGINE_ID_EDMA_0 ; i <= GAUDI3_HDCORE6_ENGINE_ID_ROT_1 ; i++) {
		if (!gaudi3_is_engine_enabled(hdev, i))
			continue;

		j = i - GAUDI3_HDCORE1_ENGINE_ID_EDMA_0;
		sob = &msg_info[j].sob;

		rc = gaudi3_test_qman_wait_completion(hdev, i, "QMAN CQF", sob->addr, sob->val);
		/* Clear the SOB value */
		WREG32(sob->addr, 0);
		if (rc)
			return rc;
	}

	/* send messages on all QMAN ARCs */
	for (i = GAUDI3_HDCORE1_ENGINE_ID_EDMA_0 ; i <= GAUDI3_HDCORE6_ENGINE_ID_ROT_1 ; i++) {
		if (!gaudi3_is_engine_enabled(hdev, i))
			continue;

		j = i - GAUDI3_HDCORE1_ENGINE_ID_EDMA_0;
		pkt_dma_addr = msg_info[j].dma_addr;

		gaudi3_test_qman_arc_send_msg(hdev, i, pkt_dma_addr, pkt_size);
	}

	/* test the CPU-Q while QMAN ARCs are working */
	rc = gaudi3_test_cpu_queue(hdev);
	if (rc)
		return rc;

	/* wait for ARCs completion */
	for (i = GAUDI3_HDCORE1_ENGINE_ID_EDMA_0 ; i <= GAUDI3_HDCORE6_ENGINE_ID_ROT_1 ; i++) {
		if (!gaudi3_is_engine_enabled(hdev, i))
			continue;

		j = i - GAUDI3_HDCORE1_ENGINE_ID_EDMA_0;
		sob = &msg_info[j].sob;

		rc = gaudi3_test_qman_wait_completion(hdev,
						      i, "QMAN ARC_CQF", sob->addr, sob->val);
		/* Clear the SOB value */
		WREG32(sob->addr, 0);

		gaudi3_qman_set_test_mode(hdev, i, false);

		if (rc)
			return rc;
	}

	return 0;
}

int gaudi3_test_cpu_queue(struct hl_device *hdev)
{
	struct gaudi3_device *gaudi3 = hdev->asic_specific;

	/* send_cpu_message() won't update the result value if no capability */
	if (!(gaudi3->hw_cap_initialized & HW_CAP_CPU_Q))
		return 0;

	return hl_fw_test_cpu_queue(hdev);
}

int gaudi3_test_queues(struct hl_device *hdev)
{
	struct gaudi3_device *gaudi3 = hdev->asic_specific;
	int rc;

	/* TODO: used for debug, so can be removed once H9-5315 is resolved.
	 * The reset value is 0x3, and we force 0x2 (turn off bit 0)
	 * as there's a PLDM trigger expecting this change to take place.
	 */
	WREG32(mmD0_NRTR0_CRDT_RRTR_OB_CRDT_BASE + mmNRTR_CRDT_RRTR_OB_CRDT_CRDT_EN, 0x2);

	dev_dbg(hdev->dev, "Testing PDMA access on %lu channels\n",
						hweight_long(gaudi3->hw_cap_pdma_initialized));

	rc = gaudi3_test_pdma_access(hdev);
	if (rc)
		return rc;

	/* TODO: used for debug, so can be removed once H9-5315 is resolved */
	WREG32(mmD0_NRTR0_CRDT_RRTR_OB_CRDT_BASE + mmNRTR_CRDT_RRTR_OB_CRDT_CRDT_EN, 0x3);

	rc = gaudi3_test_qmans_kdma_and_cpu(hdev);
	if (rc)
		return rc;

	dev_dbg(hdev->dev, "Test queues done successfully\n");

	return 0;
}

void *gaudi3_dma_pool_zalloc(struct hl_device *hdev, size_t size,
				gfp_t mem_flags, dma_addr_t *dma_handle)
{
	if (size > GAUDI3_DMA_POOL_BLK_SIZE)
		return NULL;

	return dma_pool_zalloc(hdev->dma_pool, mem_flags, dma_handle);
}

void gaudi3_dma_pool_free(struct hl_device *hdev, void *vaddr, dma_addr_t dma_addr)
{
	dma_pool_free(hdev->dma_pool, vaddr, dma_addr);
}

void *gaudi3_cpu_accessible_dma_pool_alloc(struct hl_device *hdev,
					size_t size, dma_addr_t *dma_handle)
{
	return hl_fw_cpu_accessible_dma_pool_alloc(hdev, size, dma_handle);
}

void gaudi3_cpu_accessible_dma_pool_free(struct hl_device *hdev, size_t size,
					void *vaddr)
{
	hl_fw_cpu_accessible_dma_pool_free(hdev, size, vaddr);
}

static void gaudi3_dma_unmap_page(struct hl_device *hdev, dma_addr_t addr,
			int len, enum dma_data_direction dir)
{
	dma_unmap_page(&hdev->pdev->dev, addr, len, dir);
}

static dma_addr_t gaudi3_dma_map_page(struct hl_device *hdev, struct page *page,
			int offset, int len, enum dma_data_direction dir)
{
	dma_addr_t dma_addr;

	dma_addr = dma_map_page(&hdev->pdev->dev, page, offset, len, dir);
	if (unlikely(dma_mapping_error(&hdev->pdev->dev, dma_addr)))
		return 0;

	return dma_addr;
}

