void gaudi3_set_pci_memory_regions(struct hl_device *hdev)
{
	struct asic_fixed_properties *prop = &hdev->asic_prop;
	struct pci_mem_region *region;

	/* CFG */
	region = &hdev->pci_mem_region[PCI_REGION_CFG];
	region->region_base = CFG_BAR_BASE;
	region->region_size = CFG_BAR_SIZE;
	region->offset_in_bar = 0;
	region->bar_size = CFG_BAR_SIZE;
	region->bar_id = CFG_BAR_ID;
	region->used = 1;

	/* SRAM */
	region = &hdev->pci_mem_region[PCI_REGION_SRAM];
	region->region_base = prop->sram_base_address;
	region->region_size = prop->sram_size;
	if (hdev->pdev)
		region->offset_in_bar = SRAM_SIZE - prop->sram_size;
	else
		/* simulator sets pcie_bar base at the correct offset */
		region->offset_in_bar = 0;
	region->bar_size = SRAM_SIZE + prop->dram_pci_bar_size;
	region->bar_id = SRAM_DRAM_BAR_ID;
	region->used = 1;

	/* DRAM */
	region = &hdev->pci_mem_region[PCI_REGION_DRAM];
	region->region_base = DRAM_PHYS_BASE;
	region->region_size = hdev->asic_prop.dram_size;
	region->offset_in_bar = SRAM_SIZE;
	region->bar_size = SRAM_SIZE + prop->dram_pci_bar_size;
	region->bar_id = SRAM_DRAM_BAR_ID;
	region->used = 1;

	/* FW MEM */
	region = &hdev->pci_mem_region[PCI_REGION_FW_MEM];
	region->region_base = FW_MEM_BASE;
	region->region_size = FW_MEM_SIZE;
	region->offset_in_bar = SRAM_SIZE;
	region->bar_size = SRAM_SIZE + prop->dram_pci_bar_size;
	region->bar_id = SRAM_DRAM_BAR_ID;
	region->used = 1;
}

