static void gaudi3_pmmu_cache_inv_trig(struct hl_device *hdev, void *data)
{
	struct gaudi3_mmu_maint_data *maint_data = data;

	if (maint_data->range_maint) {
		/* Invalidate range */
		WREG32(mmD0_PMMU_HBW_MMU_BASE + mmMMU_INV_START_RANGE_LO,
			lower_32_bits(maint_data->start_addr));
		WREG32(mmD0_PMMU_HBW_MMU_BASE + mmMMU_INV_START_RANGE_HI,
			upper_32_bits(maint_data->start_addr));
		WREG32(mmD0_PMMU_HBW_MMU_BASE + mmMMU_INV_END_RANGE_LO,
			lower_32_bits(maint_data->end_addr));
		WREG32(mmD0_PMMU_HBW_MMU_BASE + mmMMU_INV_END_RANGE_HI,
			upper_32_bits(maint_data->end_addr));
		WREG32(mmD0_PMMU_HBW_MMU_BASE + mmMMU_INV_ASID,
			lower_32_bits(maint_data->asid));
		WREG32(mmD0_PMMU_HBW_MMU_BASE + mmMMU_INV_RANGE_TRIGGER, 1);
	} else {
		/* Invalidate all */
		WREG32(mmD0_PMMU_HBW_MMU_BASE + mmMMU_INV_ALL_START, 1);
	}
}

static void gaudi3_hmmus_cache_maint_trig(struct hl_device *hdev, void *data)
{
	struct gaudi3_mmu_maint_data *maint_data = (struct gaudi3_mmu_maint_data *)data;
	u8 maint_type;

	if (maint_data->range_maint) {
		u32 start_off, end_off;

		maint_type = 0x1; /* 0x1- execute on all range and ASID */
		if  (maint_data->maint_type == GAUDI3_CACHE_MAINT_INV) {
			start_off = mmSTLB_INV_VA_START;
			end_off = mmSTLB_INV_VA_END;
		} else {
			start_off = mmSTLB_PF_VA_START;
			end_off = mmSTLB_PF_VA_END;
		}

		gaudi3_lbw_dup_group_push(hdev, GAUDI3_DUP_GRP_STLB_BASE, start_off,
				FIELD_GET(STLB_INV_VA_ADDR_47_20_MASK, maint_data->start_addr));
		gaudi3_lbw_dup_group_push(hdev, GAUDI3_DUP_GRP_STLB_BASE, end_off,
				FIELD_GET(STLB_INV_VA_ADDR_47_20_MASK, maint_data->end_addr));
	} else {
		maint_type = 0x3; /* 0x3- invalidate all */
	}

	/* trigger maintenance command */
	gaudi3_lbw_dup_group_push(hdev, GAUDI3_DUP_GRP_STLB_BASE, mmSTLB_MAINT_TRIGGER,
		FIELD_PREP(STLB_MAINT_TRIGGER_ASID_M, maint_data->asid) |
		FIELD_PREP(STLB_MAINT_TRIGGER_INV_OR_PF_M, maint_data->maint_type) |
		FIELD_PREP(STLB_MAINT_TRIGGER_TARGET_TYPE_M, maint_type) |
		FIELD_PREP(STLB_MAINT_TRIGGER_ID_M, 0) /* JOB ID is 0 (only one running) */);
}

static void gaudi3_set_hmmu_cq_mode_params(struct hl_device *hdev,
						struct gaudi3_cq_mode_params *cq_mode_params,
						struct gaudi3_mmu_maint_data *maint_data,
						u64 timeout_usec, u8 job_id)
{
	cq_mode_params->job_data = maint_data;
	cq_mode_params->job = gaudi3_hmmus_cache_maint_trig;
	cq_mode_params->timeout_usec = timeout_usec;
	cq_mode_params->target_sob_value = NUM_OF_STLB_PER_HDCORE * hdev->asic_prop.num_of_hdcores;
	cq_mode_params->sob_id = GAUDI3_RESERVED_SOB_HMMU_MAINT_JOB_0 + job_id;
	cq_mode_params->mon_id = GAUDI3_RESERVED_MON_HMMU_MAINT_JOB_0 + job_id;
	cq_mode_params->cq_id = GAUDI3_RESERVED_CQ_HMMU_MAINT_JOB_0 + job_id;
}

static void gaudi3_set_pmmu_cq_mode_params(struct gaudi3_cq_mode_params *cq_mode_params,
						struct gaudi3_mmu_maint_data *maint_data,
						u64 timeout_usec)
{
	cq_mode_params->job_data = maint_data;
	cq_mode_params->job = gaudi3_pmmu_cache_inv_trig;
	cq_mode_params->timeout_usec = timeout_usec;
	cq_mode_params->target_sob_value = 1; /* we have only PMMU0 */
	cq_mode_params->sob_id = GAUDI3_RESERVED_SOB_PMMU_CACHE_INV;
	cq_mode_params->mon_id = GAUDI3_RESERVED_MON_PMMU_CACHE_INV;
	cq_mode_params->cq_id = GAUDI3_RESERVED_CQ_PMMU_INV_CMPL;
}

int gaudi3_mmu_invalidate_cache(struct hl_device *hdev, bool is_hard, u32 flags)
{
	struct gaudi3_device *gaudi3 = hdev->asic_specific;
	struct gaudi3_cq_mode_params cq_mode_params = { NULL };
	struct gaudi3_mmu_maint_data maint_data = {0};
	u64 timeout_usec;

	if (hdev->reset_info.hard_reset_pending)
		return 0;

	timeout_usec = (hdev->pldm) ?
				GAUDI3_PLDM_MMU_TIMEOUT_USEC :
				GAUDI3_MMU_CACHE_MAINT_TIMEOUT_USEC;

	maint_data.range_maint = false;
	maint_data.maint_type = GAUDI3_CACHE_MAINT_INV;
	maint_data.asid = HL_KERNEL_ASID_ID;

	if ((flags & VM_TYPE_USERPTR) && (gaudi3->hw_cap_initialized & HW_CAP_PMMU)) {
		gaudi3_set_pmmu_cq_mode_params(&cq_mode_params, &maint_data, timeout_usec);
		cq_mode_params.job_str = "PMMU invalidation";
	} else if ((flags & VM_TYPE_PHYS_PACK) && (gaudi3->hw_cap_initialized & HW_CAP_HMMU_MASK)) {
		/* currently we are using only JOB 0 */
		gaudi3_set_hmmu_cq_mode_params(hdev, &cq_mode_params, &maint_data, timeout_usec, 0);
		cq_mode_params.job_str = "HMMU invalidation";
	} else {
		return 0;
	}

	return gaudi3_trigger_job_and_wait_for_cq_completion(hdev, &cq_mode_params);
}

static int gaudi3_mmu_cache_range_maint(struct hl_device *hdev, bool is_hard,
				u32 flags, u32 asid, u64 va, u64 size, bool is_prefetch)
{
	struct gaudi3_device *gaudi3 = hdev->asic_specific;
	struct gaudi3_cq_mode_params cq_mode_params = { NULL };
	struct gaudi3_mmu_maint_data maint_data = {0};
	u64 timeout_usec, last_va;
	int rc;

	if (hdev->reset_info.hard_reset_pending)
		return 0;

	if (!gaudi3)
		return -EINVAL;

	timeout_usec = (hdev->pldm) ?
				GAUDI3_PLDM_MMU_TIMEOUT_USEC :
				GAUDI3_MMU_CACHE_MAINT_TIMEOUT_USEC;

	maint_data.maint_type = is_prefetch ? GAUDI3_CACHE_MAINT_PF : GAUDI3_CACHE_MAINT_INV;
	maint_data.range_maint = true;
	maint_data.asid = asid;

	/*
	 * invalidation range is inclusive for both PMMU and HMMU.
	 * inclusive means that the end address will be invalidated as opposed
	 * to exclusive in which the end address is just the upper boundary
	 */

	/* PMMU does not support prefetch */
	if ((flags & VM_TYPE_USERPTR) &&
			(gaudi3->hw_cap_initialized & HW_CAP_PMMU) &&
			!is_prefetch) {
		maint_data.start_addr = va;
		maint_data.end_addr = maint_data.start_addr + size - 1;
		gaudi3_set_pmmu_cq_mode_params(&cq_mode_params, &maint_data, timeout_usec);
		cq_mode_params.job_str = "PMMU range invalidation";
		return gaudi3_trigger_job_and_wait_for_cq_completion(hdev, &cq_mode_params);
	} else if ((flags & VM_TYPE_PHYS_PACK) && (gaudi3->hw_cap_initialized & HW_CAP_HMMU_MASK)) {
		/* currently we are executing only a single job (JOB 0) */
		gaudi3_set_hmmu_cq_mode_params(hdev, &cq_mode_params, &maint_data, timeout_usec, 0);
		cq_mode_params.job_str = "HMMU range invalidation";

		/*
		 * due to H9-5099, when there is range invalidation with a range greater than
		 * 256MB, the DTLB will invalidate only the first 256MB and will skip all the
		 * rest. to overcome the issue a SW W/A is added to split large range
		 * into 256MB sub ranges.
		 * note that there are no alignment requirements on the small regions.
		 */
		maint_data.start_addr = va;
		maint_data.end_addr = maint_data.start_addr + RANGE_INV_MAX_MEM_SIZE - 1;
		last_va = maint_data.start_addr + size;
		while (maint_data.end_addr < last_va) {
			rc = gaudi3_trigger_job_and_wait_for_cq_completion(hdev, &cq_mode_params);
			if (rc)
				return rc;
			maint_data.start_addr += RANGE_INV_MAX_MEM_SIZE;
			maint_data.end_addr += RANGE_INV_MAX_MEM_SIZE;
		}

		/* should invalidate the residual range (the mod 256M) */
		if (maint_data.start_addr < last_va) {
			maint_data.end_addr = last_va - 1;
			rc = gaudi3_trigger_job_and_wait_for_cq_completion(hdev, &cq_mode_params);
			if (rc)
				return rc;
		}
	}

	return 0;
}

int gaudi3_mmu_invalidate_cache_range(struct hl_device *hdev, bool is_hard, u32 flags, u32 asid,
					u64 va, u64 size)
{
	return gaudi3_mmu_cache_range_maint(hdev, is_hard, flags, asid, va, size, false);
}

int gaudi3_mmu_prefetch_cache_range(struct hl_ctx *ctx, u32 flags, u32 asid, u64 va, u64 size)
{
	return gaudi3_mmu_cache_range_maint(ctx->hdev, false, flags, asid, va, size, true);
}

int gaudi3_send_heartbeat(struct hl_device *hdev)
{
	struct gaudi3_device *gaudi3 = hdev->asic_specific;

	if (!(gaudi3->hw_cap_initialized & HW_CAP_CPU_Q))
		return 0;

	return hl_fw_send_heartbeat(hdev);
}

static void gaudi3_is_pdma_group_idle(struct hl_device *hdev, int die, int inst, u32 offset,
					struct iterate_module_ctx *ctx)
{
	u32 reg_base, pqm_glbl_sts, pqm_cgm_sts, dma_status, ch_sts, ch_id;
	bool is_pqm_idle = true, is_dma_idle = true, is_idle;
	const char *format = "%-5d%-6d%-9s%#-14x%#-13x%#x\n";
	struct gaudi3_idle_data *idle_data = ctx->data;
	long eng_id_base;

	reg_base = mmD0_SPDMA0_CMN_B_BASE + offset;

	pqm_glbl_sts = RREG32(reg_base + mmPDMA_CMN_B_PQM_CMN_B_GLBL_STS);
	if ((FIELD_GET(PDMA_CMN_B_PQM_CMN_B_GLBL_STS_STS_CP_IDLE_M, pqm_glbl_sts) != 0x1) ||
			(FIELD_GET(PDMA_CMN_B_PQM_CMN_B_GLBL_STS_STS_CQ_IDLE_M,
									pqm_glbl_sts) != 0x1) ||
			(FIELD_GET(PDMA_CMN_B_PQM_CMN_B_GLBL_STS_ENGINE_BUSY_M,
									pqm_glbl_sts) != 0x0))
		is_pqm_idle = false;

	pqm_cgm_sts = RREG32(reg_base + mmPDMA_CMN_B_PQM_CMN_B_CGM_STS);
	if ((FIELD_GET(PDMA_CMN_B_PQM_CMN_B_CGM_STS_AGENT_IDLE_M, pqm_cgm_sts) != 0x1) ||
			(FIELD_GET(PDMA_CMN_B_PQM_CMN_B_CGM_STS_AXI_IDLE_M, pqm_cgm_sts) != 0x1) ||
			(FIELD_GET(PDMA_CMN_B_PQM_CMN_B_CGM_STS_CP_IDLE_M, pqm_cgm_sts) != 0x1))
		is_pqm_idle = false;

	dma_status = RREG32(reg_base + mmPDMA_CMN_B_DMA_STATUS);
	if (FIELD_GET(PDMA_CMN_B_DMA_STATUS_IDLE_M, dma_status) != 0x0)
		is_dma_idle = false;

	is_idle = (is_pqm_idle && is_dma_idle);

	if (idle_data->mask && !is_idle) {
		eng_id_base = GAUDI3_DIE0_ENGINE_ID_PDMA_0_CH_0 +
				die * NUM_OF_PDMA_GRP_PER_DIE * NUM_OF_PDMA_CH_PER_GRP +
				inst * NUM_OF_PDMA_CH_PER_GRP;
		ch_sts = FIELD_GET(PDMA_CMN_B_DMA_STATUS_IDLE_M, dma_status);

		/* Mark as not idle if either the PQM or the specific channel are not idle */
		for (ch_id = 0 ; ch_id < NUM_OF_PDMA_CH_PER_GRP ; ch_id++)
			if (!is_pqm_idle || (ch_sts & BIT(ch_id)))
				__set_bit(eng_id_base + ch_id, idle_data->mask);
	}

	if (idle_data->e)
		hl_engine_data_sprintf(idle_data->e, format, die, inst, is_idle ? "Y" : "N",
					pqm_glbl_sts, pqm_cgm_sts, dma_status);

	*idle_data->is_idle &= is_idle;
}

static void gaudi3_get_pdma_idle_status(struct hl_device *hdev, struct gaudi3_idle_data *idle_data)
{
	const char *header = "\nDIE  PDMA  is_idle  PQM_GLBL_STS  PQM_CGM_STS  DMA_STATUS\n"
				"---  ----  -------  ------------  -----------  ----------\n";
	struct iterate_module_ctx iter_ctx = {
		.fn = gaudi3_is_pdma_group_idle,
		.data = idle_data
	};

	if (idle_data->e)
		hl_engine_data_sprintf(idle_data->e, header);

	gaudi3_iterate_pdma_grps(hdev, &iter_ctx);
}

static void gaudi3_is_pdma_dup_idle(struct hl_device *hdev, int die, int inst, u32 offset,
					struct iterate_module_ctx *ctx)
{
	struct gaudi3_idle_data *idle_data = ctx->data;
	const char *format = "%-5d%-10d%-9s%#x\n";
	u32 reg_base, dup_status;
	bool is_idle = true;
	long eng_id;

	reg_base = mmD0_SPDMA0_DUP_ENG_BASE + offset;
	dup_status = RREG32(reg_base + mmPDUP_ENG_DUP_STATUS);
	if (FIELD_GET(PDUP_ENG_DUP_STATUS_BUSY_M, dup_status) != 0x0)
		is_idle = false;

	if (idle_data->mask && !is_idle) {
		eng_id = GAUDI3_DIE0_ENGINE_ID_PDMA_0_DUP + die * LBW_DUP_NUMBER_OF_ENGINES + inst;
		__set_bit(eng_id, idle_data->mask);
	}

	if (idle_data->e)
		hl_engine_data_sprintf(idle_data->e, format, die, inst, is_idle ? "Y" : "N",
					dup_status);

	*idle_data->is_idle &= is_idle;
}

static void gaudi3_get_pdma_dup_idle_status(struct hl_device *hdev,
						struct gaudi3_idle_data *idle_data)
{
	const char *header = "\nDIE  PDMA_DUP  is_idle  DUP_STATUS\n"
				"---  --------  -------  ----------\n";
	struct iterate_module_ctx iter_ctx = {
		.fn = gaudi3_is_pdma_dup_idle,
		.data = idle_data
	};

	if (idle_data->e)
		hl_engine_data_sprintf(idle_data->e, header);

	gaudi3_iterate_pdma_grps(hdev, &iter_ctx);
}

static bool gaudi3_is_qman_idle(struct hl_device *hdev, u32 reg_base, u32 *glbl_sts0,
				u32 *glbl_sts1, u32 *cgm_sts)
{
	bool is_idle = true;

	*glbl_sts0 = RREG32(reg_base + mmQMAN_GLBL_STS0);
	if ((FIELD_GET(QMAN_GLBL_STS0_CQF_IDLE_M, *glbl_sts0) != 0x1) ||
			(FIELD_GET(QMAN_GLBL_STS0_CP_IDLE_M, *glbl_sts0) != 0x1))
		is_idle = false;

	*glbl_sts1 = RREG32(reg_base + mmQMAN_GLBL_STS1);
	if (FIELD_GET(QMAN_GLBL_STS1_ARC_CQF_IDLE_M, *glbl_sts1) != 0x1)
		is_idle = false;

	*cgm_sts = RREG32(reg_base + QM_CGM_BASE_OFFSET + mmQMAN_CGM_STS);
	if ((FIELD_GET(QMAN_CGM_STS_AGENT_IDLE_M, *cgm_sts) != 0x1) ||
			(FIELD_GET(QMAN_CGM_STS_AXI_IDLE_M, *cgm_sts) != 0x1) ||
			(FIELD_GET(QMAN_CGM_STS_CP_IDLE_M, *cgm_sts) != 0x1) ||
			(FIELD_GET(QMAN_CGM_STS_AXI_WR_IDLE_M, *cgm_sts) != 0x1))
		is_idle = false;

	return is_idle;
}

static void gaudi3_is_edma_engine_idle(struct hl_device *hdev, int hdcore, int inst, u32 offset,
					struct iterate_module_ctx *ctx)
{
	u32 reg_base, qm_glbl_sts0, qm_glbl_sts1, qm_cgm_sts, dma_status, dbg_sts, hdcore_index;
	const char *format = "%-4d%-6d%-9s%#-14x%#-14x%#-12x%#-12x%#x\n";
	struct gaudi3_idle_data *idle_data = ctx->data;
	bool is_idle = true;
	long eng_id;

	reg_base = mmHD1_SEDMA0_QM_BASE + offset;
	if (!gaudi3_is_qman_idle(hdev, reg_base, &qm_glbl_sts0, &qm_glbl_sts1, &qm_cgm_sts))
		is_idle = false;

	reg_base = mmHD1_SEDMA0_CMN_BASE + offset;

	dma_status = RREG32(reg_base + mmEDMA_CMN_DMA_STATUS);
	if ((FIELD_GET(EDMA_CMN_DMA_STATUS_STATUS_CH0_M, dma_status) != 0x0) ||
			(FIELD_GET(EDMA_CMN_DMA_STATUS_STATUS_CH1_M, dma_status) != 0x0) ||
			(FIELD_GET(EDMA_CMN_DMA_STATUS_STATUS_CH2_M, dma_status) != 0x0))
		is_idle = false;

	dbg_sts = RREG32(reg_base + mmEDMA_CMN_DBG_STS);
	if ((FIELD_GET(EDMA_CMN_DBG_STS_TE_BUSY_M, dbg_sts) != 0x0) ||
			(FIELD_GET(EDMA_CMN_DBG_STS_TE_EMPTY_M, dbg_sts) != 0x1) ||
			(FIELD_GET(EDMA_CMN_DBG_STS_RD_BUF_EMPTY_M, dbg_sts) != 0x1) ||
			(FIELD_GET(EDMA_CMN_DBG_STS_RD_BUF_NO_INFLIGHT_M, dbg_sts) != 0x1) ||
			(FIELD_GET(EDMA_CMN_DBG_STS_WR_BUF_EMPTY_M, dbg_sts) != 0x1) ||
			(FIELD_GET(EDMA_CMN_DBG_STS_WR_BUF_NO_INFLIGHT_M, dbg_sts) != 0x1) ||
			(FIELD_GET(EDMA_CMN_DBG_STS_HBW_FULLNESS_M, dbg_sts) != 0x0) ||
			(FIELD_GET(EDMA_CMN_DBG_STS_LBW_FULLNESS_M, dbg_sts) != 0x0))
		is_idle = false;

	if (idle_data->mask && !is_idle) {
		hdcore_index = hdcore / 2; /* [0] = HD1, [1] = HD3, [2] = HD4, [3] = HD6 */
		eng_id = GAUDI3_HDCORE1_ENGINE_ID_EDMA_0 + hdcore_index * NUM_OF_EDMA_PER_HDCORE +
				inst;
		__set_bit(eng_id, idle_data->mask);
	}

	if (idle_data->e)
		hl_engine_data_sprintf(idle_data->e, format, hdcore, inst, is_idle ? "Y" : "N",
				qm_glbl_sts0, qm_glbl_sts1, qm_cgm_sts, dma_status, dbg_sts);

	*idle_data->is_idle &= is_idle;
}

static void gaudi3_get_emda_idle_status(struct hl_device *hdev, struct gaudi3_idle_data *idle_data)
{
	const char *header =
		"\nHD  EDMA  is_idle  QM_GLBL_STS0  QM_GLBL_STS1  QM_CGM_STS  DMA_STATUS  DBG_STS\n"
		"--  ----  -------  ------------  ------------  ----------  ----------  -------\n"
		;
	struct iterate_module_ctx iter_ctx = {
		.fn = gaudi3_is_edma_engine_idle,
		.data = idle_data
	};

	if (idle_data->e && hdev->asic_prop.edma_enabled_mask)
		hl_engine_data_sprintf(idle_data->e, header);

	gaudi3_iterate_edmas(hdev, &iter_ctx);
}

static void gaudi3_is_tpc_engine_idle(struct hl_device *hdev, int hdcore, int inst, u32 offset,
					struct iterate_module_ctx *ctx)
{
	u32 reg_base, qm_glbl_sts0, qm_glbl_sts1, qm_cgm_sts, status, tsb_inflight_cntr,
		wq_inflight_cntr;
	const char *format = "%-4d%-5d%-9s%#-14x%#-14x%#-12x%#-12x%#-19x%#x\n";
	struct gaudi3_idle_data *idle_data = ctx->data;
	bool is_idle = true;
	long eng_id;

	reg_base = mmHD0_TPC0_QM_BASE + offset;
	if (!gaudi3_is_qman_idle(hdev, reg_base, &qm_glbl_sts0, &qm_glbl_sts1, &qm_cgm_sts))
		is_idle = false;

	reg_base = mmHD0_TPC0_CFG_BASE + offset;

	status = RREG32(reg_base + mmTPC_STATUS);
	if ((FIELD_GET(TPC_STATUS_SCALAR_PIPE_EMPTY_M, status) != 0x1) ||
			(FIELD_GET(TPC_STATUS_IQ_EMPTY_M, status) != 0x1) ||
			(FIELD_GET(TPC_STATUS_SB_EMPTY_M, status) != 0x1) ||
			(FIELD_GET(TPC_STATUS_QM_IDLE_M, status) != 0x1) ||
			(FIELD_GET(TPC_STATUS_QM_RDY_M, status) != 0x1))
		is_idle = false;

	tsb_inflight_cntr = RREG32(reg_base + mmTPC_TSB_INFLIGHT_CNTR);
	if (FIELD_GET(TPC_TSB_INFLIGHT_CNTR_V_M, tsb_inflight_cntr) != 0x0)
		is_idle = false;

	wq_inflight_cntr = RREG32(reg_base + mmTPC_WQ_INFLIGHT_CNTR);
	if ((FIELD_GET(TPC_WQ_INFLIGHT_CNTR_HBW_M, wq_inflight_cntr) != 0x0) ||
			(FIELD_GET(TPC_WQ_INFLIGHT_CNTR_LBW_M, wq_inflight_cntr) != 0x0))
		is_idle = false;

	if (idle_data->mask && !is_idle) {
		eng_id = GAUDI3_HDCORE0_ENGINE_ID_TPC_0 + hdcore * NUM_OF_TPC_PER_HDCORE + inst;
		__set_bit(eng_id, idle_data->mask);
	}

	if (idle_data->e)
		hl_engine_data_sprintf(idle_data->e, format, hdcore, inst, is_idle ? "Y" : "N",
					qm_glbl_sts0, qm_glbl_sts1, qm_cgm_sts,
					status, tsb_inflight_cntr, wq_inflight_cntr);

	*idle_data->is_idle &= is_idle;
}

static void gaudi3_get_tpc_idle_status(struct hl_device *hdev, struct gaudi3_idle_data *idle_data)
{
	const char *header =
		"\nHD  TPC  is_idle  QM_GLBL_STS0  QM_GLBL_STS1  QM_CGM_STS  STATUS      TSB_INFLIGHT_CNTR  WQ_INFLIGHT_CNTR\n"
		"--  ---  -------  ------------  ------------  ----------  ------      -----------------  ----------------\n"
		;
	struct iterate_module_ctx iter_ctx = {
		.fn = gaudi3_is_tpc_engine_idle,
		.data = idle_data
	};

	if (idle_data->e && hdev->asic_prop.tpc_enabled_mask)
		hl_engine_data_sprintf(idle_data->e, header);

	gaudi3_iterate_tpcs(hdev, &iter_ctx);
}

static void gaudi3_is_mme_engine_idle(struct hl_device *hdev, int hdcore, int inst, u32 offset,
					struct iterate_module_ctx *ctx)
{
	u32 reg_base, qm_glbl_sts0, qm_glbl_sts1, qm_cgm_sts, arch_status_master, arch_status_slave;
	const char *format = "%-4d%-5d%-9s%#-14x%#-14x%#-12x%#-20x%#x\n";
	struct gaudi3_idle_data *idle_data = ctx->data;
	bool is_idle = true;
	long eng_id;

	reg_base = mmHD0_MME_QM_BASE + offset;
	if (!gaudi3_is_qman_idle(hdev, reg_base, &qm_glbl_sts0, &qm_glbl_sts1, &qm_cgm_sts))
		is_idle = false;

	reg_base = mmHD0_MME_CTRL_LO_BASE + offset;

	arch_status_master = RREG32(reg_base + mmMME_CTRL_LO_ARCH_STATUS_MASTER);
	if ((FIELD_GET(MME_CTRL_LO_ARCH_STATUS_MASTER_AGU_IN_M, arch_status_master) != 0x0) ||
			(FIELD_GET(MME_CTRL_LO_ARCH_STATUS_MASTER_EU_M,
								arch_status_master) != 0x0) ||
			(FIELD_GET(MME_CTRL_LO_ARCH_STATUS_MASTER_AP_M,
								arch_status_master) != 0x0) ||
			(FIELD_GET(MME_CTRL_LO_ARCH_STATUS_MASTER_AGU_COUT_M,
								arch_status_master) != 0x0) ||
			(FIELD_GET(MME_CTRL_LO_ARCH_STATUS_MASTER_AGU_DMA_O_M,
								arch_status_master) != 0x0) ||
			(FIELD_GET(MME_CTRL_LO_ARCH_STATUS_MASTER_SB_IN_EMPTY_M,
								arch_status_master) != 0xF) ||
			(FIELD_GET(MME_CTRL_LO_ARCH_STATUS_MASTER_AGU_COUT_SM_IDLE_M,
								arch_status_master) != 0x1) ||
			(FIELD_GET(MME_CTRL_LO_ARCH_STATUS_MASTER_AGU_DMA_O_SM_IDLE_M,
								arch_status_master) != 0x1) ||
			(FIELD_GET(MME_CTRL_LO_ARCH_STATUS_MASTER_WBC_AXI_IDLE_M,
								arch_status_master) != 0x1) ||
			(FIELD_GET(MME_CTRL_LO_ARCH_STATUS_MASTER_SB_IN_AXI_IDLE_M,
								arch_status_master) != 0xF) ||
			(FIELD_GET(MME_CTRL_LO_ARCH_STATUS_MASTER_QM_IDLE_M,
								arch_status_master) != 0x1) ||
			(FIELD_GET(MME_CTRL_LO_ARCH_STATUS_MASTER_QM_RDY_M,
								arch_status_master) != 0x1))
		is_idle = false;

	arch_status_slave = RREG32(reg_base + mmMME_CTRL_LO_ARCH_STATUS_SLAVE);
	if ((FIELD_GET(MME_CTRL_LO_ARCH_STATUS_SLAVE_AGU_IN_M, arch_status_master) != 0x0) ||
			(FIELD_GET(MME_CTRL_LO_ARCH_STATUS_SLAVE_EU_M,
								arch_status_master) != 0x0) ||
			(FIELD_GET(MME_CTRL_LO_ARCH_STATUS_SLAVE_AP_M,
								arch_status_master) != 0x0) ||
			(FIELD_GET(MME_CTRL_LO_ARCH_STATUS_SLAVE_AGU_COUT_M,
								arch_status_master) != 0x0) ||
			(FIELD_GET(MME_CTRL_LO_ARCH_STATUS_SLAVE_AGU_DMA_O_M,
								arch_status_master) != 0x0) ||
			(FIELD_GET(MME_CTRL_LO_ARCH_STATUS_SLAVE_SB_IN_EMPTY_M,
								arch_status_master) != 0xF) ||
			(FIELD_GET(MME_CTRL_LO_ARCH_STATUS_SLAVE_AGU_COUT_SM_IDLE_M,
								arch_status_master) != 0x1) ||
			(FIELD_GET(MME_CTRL_LO_ARCH_STATUS_SLAVE_AGU_DMA_O_SM_IDLE_M,
								arch_status_master) != 0x1) ||
			(FIELD_GET(MME_CTRL_LO_ARCH_STATUS_SLAVE_WBC_AXI_IDLE_M,
								arch_status_master) != 0x1) ||
			(FIELD_GET(MME_CTRL_LO_ARCH_STATUS_SLAVE_SB_IN_AXI_IDLE_M,
								arch_status_master) != 0xF) ||
			(FIELD_GET(MME_CTRL_LO_ARCH_STATUS_SLAVE_QM_IDLE_M,
								arch_status_master) != 0x1) ||
			(FIELD_GET(MME_CTRL_LO_ARCH_STATUS_SLAVE_QM_RDY_M,
								arch_status_master) != 0x1))
		is_idle = false;

	if (idle_data->mask && !is_idle) {
		eng_id = GAUDI3_HDCORE0_ENGINE_ID_MME_0 + hdcore;
		__set_bit(eng_id, idle_data->mask);
	}

	if (idle_data->e)
		hl_engine_data_sprintf(idle_data->e, format, hdcore, inst, is_idle ? "Y" : "N",
					qm_glbl_sts0, qm_glbl_sts1, qm_cgm_sts,
					arch_status_master, arch_status_slave);

	*idle_data->is_idle &= is_idle;
}

static void gaudi3_get_mme_idle_status(struct hl_device *hdev, struct gaudi3_idle_data *idle_data)
{
	const char *header =
		"\nHD  MME  is_idle  QM_GLBL_STS0  QM_GLBL_STS1  QM_CGM_STS  ARCH_STATUS_MASTER  ARCH_STATUS_SLAVE\n"
		"--  ---  -------  ------------  ------------  ----------  ------------------  -----------------\n"
		;
	struct iterate_module_ctx iter_ctx = {
		.fn = gaudi3_is_mme_engine_idle,
		.data = idle_data
	};

	if (idle_data->e && hdev->mme_mask)
		hl_engine_data_sprintf(idle_data->e, header);

	gaudi3_iterate_mmes(hdev, &iter_ctx);
}

static void gaudi3_is_rotator_engine_idle(struct hl_device *hdev, int hdcore, int inst, u32 offset,
						struct iterate_module_ctx *ctx)
{
	u32 reg_base, qm_glbl_sts0, qm_glbl_sts1, qm_cgm_sts, rsb_info, wbc_info, hdcore_index;
	const char *format = "%-4d%-5d%-9s%#-14x%#-14x%#-12x%#-12x%#x\n";
	struct gaudi3_idle_data *idle_data = ctx->data;
	bool is_idle = true;
	long eng_id;

	reg_base = mmHD1_ROT0_QM_BASE + offset;
	if (!gaudi3_is_qman_idle(hdev, reg_base, &qm_glbl_sts0, &qm_glbl_sts1, &qm_cgm_sts))
		is_idle = false;

	reg_base = mmHD1_ROT0_BASE + offset;

	rsb_info = RREG32(reg_base + mmROTATOR_RSB_INFO);
	if ((FIELD_GET(ROTATOR_RSB_INFO_EMPTY_M, rsb_info) != 0x1) ||
			(FIELD_GET(ROTATOR_RSB_INFO_AXI_IDLE_M, rsb_info) != 0x1))
		is_idle = false;

	wbc_info = RREG32(reg_base + mmROTATOR_WBC_INFO);
	if ((FIELD_GET(ROTATOR_WBC_INFO_EMPTY_M, wbc_info) != 0x1) ||
			(FIELD_GET(ROTATOR_WBC_INFO_AXI_IDLE_M, wbc_info) != 0x1))
		is_idle = false;

	if (idle_data->mask && !is_idle) {
		hdcore_index = hdcore / 2; /* [0] = HD1, [1] = HD3, [2] = HD4, [3] = HD6 */
		eng_id = GAUDI3_HDCORE1_ENGINE_ID_ROT_0 + hdcore_index * NUM_OF_ROTATOR_PER_HDCORE +
				inst;
		__set_bit(eng_id, idle_data->mask);
	}

	if (idle_data->e)
		hl_engine_data_sprintf(idle_data->e, format, hdcore, inst, is_idle ? "Y" : "N",
					qm_glbl_sts0, qm_glbl_sts1, qm_cgm_sts, rsb_info, wbc_info);

	*idle_data->is_idle &= is_idle;
}

static void gaudi3_get_rotator_idle_status(struct hl_device *hdev,
						struct gaudi3_idle_data *idle_data)
{
	const char *header =
		"\nHD  ROT  is_idle  QM_GLBL_STS0  QM_GLBL_STS1  QM_CGM_STS  RSB_INFO    WBC_INFO\n"
		"--  ---  -------  ------------  ------------  ----------  --------    --------\n";
	struct iterate_module_ctx iter_ctx = {
		.fn = gaudi3_is_rotator_engine_idle,
		.data = idle_data
	};

	if (idle_data->e && hdev->asic_prop.rotator_enabled_mask)
		hl_engine_data_sprintf(idle_data->e, header);

	gaudi3_iterate_rotators(hdev, &iter_ctx);
}

static void gaudi3_is_decoder_engine_idle(struct hl_device *hdev, int hdcore, int inst, u32 offset,
						struct iterate_module_ctx *ctx)
{
	struct gaudi3_idle_data *idle_data = ctx->data;
	u32 reg_base, vsi_cmd_swreg15, work_state;
	const char *format = "%-4d%-5d%-9s%#x\n";
	bool is_idle = true;
	long eng_id;

	reg_base = mmHD0_VDEC0_CMD_BASE + offset;
	vsi_cmd_swreg15 = RREG32(reg_base + mmVSI_CMD_SWREG15);
	work_state = FIELD_GET(VSI_CMD_SWREG15_SW_WORK_STATE_M, vsi_cmd_swreg15);
	if (work_state != 0x0 && work_state != 0x3) /* 0x0 = idle, 0x3 = pending */
		is_idle = false;

	if (idle_data->mask && !is_idle) {
		eng_id = GAUDI3_HDCORE0_ENGINE_ID_DEC_0 + hdcore * NUM_OF_DECODER_PER_HDCORE + inst;
		__set_bit(eng_id, idle_data->mask);
	}

	if (idle_data->e)
		hl_engine_data_sprintf(idle_data->e, format, hdcore, inst, is_idle ? "Y" : "N",
					vsi_cmd_swreg15);

	*idle_data->is_idle &= is_idle;
}

static void gaudi3_get_decoder_idle_status(struct hl_device *hdev,
						struct gaudi3_idle_data *idle_data)
{
	const char *header = "\nHD  DEC  is_idle  VSI_CMD_SWREG15\n"
				"--  ---  -------  ---------------\n";
	struct iterate_module_ctx iter_ctx = {
		.fn = gaudi3_is_decoder_engine_idle,
		.data = idle_data
	};

	if (idle_data->e && hdev->asic_prop.decoder_enabled_mask)
		hl_engine_data_sprintf(idle_data->e, header);

	gaudi3_iterate_decoders(hdev, &iter_ctx);
}

static void gaudi3_is_arc_farm_dup_idle(struct hl_device *hdev, int hdcore, int inst, u32 offset,
					struct gaudi3_idle_data *idle_data)
{
	const char *format = "%-4d%-14d%-9s%#x\n";
	u32 reg_base, dup_status;
	bool is_idle = true;
	long eng_id;

	reg_base = mmHD0_ARC_FARM_ARC0_DUP_ENG_BASE + offset;
	dup_status = RREG32(reg_base + mmARC_DUP_ENG_DUP_STATUS);
	if (FIELD_GET(ARC_DUP_ENG_DUP_STATUS_BUSY_M, dup_status) != 0x0)
		is_idle = false;

	if (idle_data->mask && !is_idle) {
		eng_id = GAUDI3_HDCORE0_ENGINE_ID_ARCF_0 + hdcore * NUM_ARC_SCHED_PER_HDCORE + inst;
		__set_bit(eng_id, idle_data->mask);
	}

	if (idle_data->e)
		hl_engine_data_sprintf(idle_data->e, format, hdcore, inst, is_idle ? "Y" : "N",
					dup_status);

	*idle_data->is_idle &= is_idle;
}

static void gaudi3_get_arc_farm_dup_idle_status(struct hl_device *hdev,
						struct gaudi3_idle_data *idle_data)
{
	const char *header = "\nHD  ARC_FARM_DUP  is_idle  DUP_STATUS\n"
				"--  ------------  -------  ----------\n";
	u32 hdcore, inst, arc_id, offset;

	if (idle_data->e && hdev->sched_arc_mask)
		hl_engine_data_sprintf(idle_data->e, header);

	for (hdcore = 0 ; hdcore < hdev->asic_prop.num_of_hdcores ; hdcore++) {
		for (inst = 0 ; inst < NUM_ARC_SCHED_PER_HDCORE ; inst++) {
			arc_id = hdcore * NUM_ARC_SCHED_PER_HDCORE + inst;
			if (!(hdev->sched_arc_mask & BIT_ULL(arc_id)))
				continue;

			offset = hdcore * HDCORE_OFFSET + inst * ARC_DUP_SCHED_OFFSET;
			gaudi3_is_arc_farm_dup_idle(hdev, hdcore, inst, offset, idle_data);
		}
	}
}

bool gaudi3_is_device_idle(struct hl_device *hdev, u64 *mask_arr, u8 mask_len,
					struct engines_data *e)
{
	unsigned long *mask = (unsigned long *) mask_arr;
	bool is_idle = true;
	struct gaudi3_idle_data idle_data = {
		.e = e,
		.mask = mask,
		.is_idle = &is_idle
	};

	gaudi3_get_pdma_idle_status(hdev, &idle_data);
	gaudi3_get_pdma_dup_idle_status(hdev, &idle_data);
	gaudi3_get_emda_idle_status(hdev, &idle_data);
	gaudi3_get_tpc_idle_status(hdev, &idle_data);
	gaudi3_get_mme_idle_status(hdev, &idle_data);
	gaudi3_get_rotator_idle_status(hdev, &idle_data);
	gaudi3_get_decoder_idle_status(hdev, &idle_data);
	gaudi3_get_arc_farm_dup_idle_status(hdev, &idle_data);

	return is_idle;
}

void gaudi3_init_cbc(struct hl_device *hdev)
{
	struct gaudi3_device *gaudi3 = hdev->asic_specific;
	u32 cbc_mode;
	int range;

	if (gaudi3->hw_cap_initialized & HW_CAP_CBC)
		return;

	cbc_mode = FIELD_PREP(CBC_CBC_MODE_RANGE_MODE_M, 0x1);

	dev_dbg(hdev->dev, "Initializing CBC\n");

	for (range = 0 ; range < NUM_OF_CBC_RANGES ; range++)
		WREG32(mmD0_PMMU_CBC_BASE + mmCBC_CBC_RANGE_ASID_CHK_EN_0 + range * sizeof(u32),
				0x1);

	WREG32(mmD0_PMMU_CBC_BASE + mmCBC_CBC_MODE, cbc_mode);
	WREG32(mmD0_PMMU_CBC_BASE + mmCBC_CBC_EN, 0x1);

	gaudi3->hw_cap_initialized |= HW_CAP_CBC;
}

static void gaudi3_disable_cbc_ranges(struct hl_device *hdev)
{
	int range;

	for (range = 0 ; range < NUM_OF_CBC_RANGES ; range++)
		WREG32(mmD0_PMMU_CBC_USER_BASE + mmCBC_USER_CBC_RANGE_EN_0 + range * sizeof(u32),
				0x0);
}

static void gaudi3_set_cbc_lbw_prot(struct hl_device *hdev, bool is_secured)
{
	WREG32(mmD0_PMMU_CBC_BASE + mmCBC_LBW_PROT1_0, is_secured ? 0x0 : 0x1);
}

static void gaudi3_invalidate_cbc(struct hl_device *hdev, void *data)
{
	u32 ctrl, sob_offset, sob_addr, lbw_addr, lbw_data;

	/* Invalidate all CBC ranges */
	ctrl = FIELD_PREP(CBC_USER_INVALID_CTRL_ALL_M, 0x1);

	/* Completion LBW message */
	sob_offset = GAUDI3_RESERVED_SOB_CBC_INVALIDATION * sizeof(u32);
	sob_addr = mmHD0_SYNC_MNGR_OBJS_BASE + mmSOB_OBJS_SOB_OBJ_0_0 + sob_offset;
	lbw_addr = lower_32_bits(sob_addr + CFG_BAR_BASE - LBW_BASE);
	lbw_data = FIELD_PREP(SOB_OBJS_SOB_OBJ_0_INC_M, 1) |
			FIELD_PREP(SOB_OBJS_SOB_OBJ_0_VAL_M, 1);

	WREG32(mmD0_PMMU_CBC_USER_BASE + mmCBC_USER_INVALID_CTRL_0, ctrl);

	WREG32(mmD0_PMMU_CBC_USER_BASE + mmCBC_USER_LBW_ADDR_0, lbw_addr);
	WREG32(mmD0_PMMU_CBC_USER_BASE + mmCBC_USER_LBW_DATA_0, lbw_data);

	WREG32(mmD0_PMMU_CBC_USER_BASE + mmCBC_USER_INVALID_EN_0, 0x1);
}

static void gaudi3_set_cbc_cq_mode_params(struct hl_device *hdev,
						struct gaudi3_cq_mode_params *cq_params)
{
	memset(cq_params, 0, sizeof(*cq_params));
	cq_params->job = gaudi3_invalidate_cbc;
	cq_params->job_data = NULL;
	cq_params->job_str = "CBC invalidation";
	cq_params->timeout_usec = hdev->pldm ? GAUDI3_PLDM_CBC_INVALIDATION_TIMEOUT_USEC :
						GAUDI3_CBC_INVALIDATION_TIMEOUT_USEC;
	cq_params->target_sob_value = 1;
	cq_params->sob_id = GAUDI3_RESERVED_SOB_CBC_INVALIDATION;
	cq_params->mon_id = GAUDI3_RESERVED_MON_CBC_INVALIDATION;
	cq_params->cq_id = GAUDI3_RESERVED_CQ_CBC_INVALIDATION;
}

static int gaudi3_reinit_cbc(struct hl_device *hdev)
{
	struct gaudi3_cq_mode_params cq_mode_params = {};
	int rc;

	gaudi3_disable_cbc_ranges(hdev);

	gaudi3_set_cbc_lbw_prot(hdev, true);
	gaudi3_set_cbc_cq_mode_params(hdev, &cq_mode_params);
	rc = gaudi3_trigger_job_and_wait_for_cq_completion(hdev, &cq_mode_params);
	if (rc)
		dev_err(hdev->dev, "Failed to invalidate CBC\n");
	gaudi3_set_cbc_lbw_prot(hdev, false);

	return rc;
}

static void gaudi3_trigger_cs_invalidation(struct hl_device *hdev, int block, int inst,
						u32 offset, struct iterate_module_ctx *ctx)
{
	WREG32(offset + CS_MAINT_BASE_OFFSET + mmCACHE_MAINT_INV_ALL, 0x1);
}

static void gaudi3_cs_invalidation_poll_status(struct hl_device *hdev, int block, int inst,
						u32 offset, struct iterate_module_ctx *ctx)
{
	u64 timeout_us;
	u32 val;

	timeout_us = hdev->pldm ? GAUDI3_PLDM_CS_INVALIDATION_TIMEOUT_USEC :
					GAUDI3_CS_INVALIDATION_TIMEOUT_USEC;

	/*
	 * wait till no more on-going invalidations and no dropped
	 * jobs (which indicates some error)
	 */
	ctx->rc = hl_poll_timeout(
			hdev,
			offset + CS_MAINT_BASE_OFFSET + mmCACHE_MAINT_STATUS,
			val,
			(val == 0x0),
			100,
			timeout_us);

	if (ctx->rc)
		dev_err(hdev->dev, "CS invalidation (%#llx) still busy\n",
			offset + CS_MAINT_BASE_OFFSET + mmCACHE_MAINT_STATUS);
}

static int gaudi3_invalidate_all_cs(struct hl_device *hdev)
{
	struct iterate_module_ctx ctx = {};

	if (!hdev->cache_enable)
		return 0;

	ctx.fn = gaudi3_trigger_cs_invalidation;
	gaudi3_iterate_cache_slices(hdev, &ctx);

	ctx.fn = gaudi3_cs_invalidation_poll_status;
	gaudi3_iterate_cache_slices(hdev, &ctx);
	if (ctx.rc)
		return ctx.rc;

	return 0;
}

int gaudi3_compute_reset_late_init(struct hl_device *hdev)
{
	int rc;

	gaudi3_init_arcs(hdev);

	rc = gaudi3_invalidate_all_cs(hdev);
	if (rc)
		return rc;

	return gaudi3_reinit_cbc(hdev);
}

