static bool gaudi3_razwi_status(struct hl_device *hdev, struct razwi_initiator_info *initiator,
				enum razwi_type type, bool is_hbw, u16 eng_id, u64 *event_mask)
{
	u32 is_razwi_happened, addr_lo, addr_hi, flags;
	u64 base, razwi_offset, razwi_addr;
	char *bw_type, *razwi_type;

	if (is_hbw) {
		base = initiator->hbw_razwi_info_base;
		bw_type = "HBW";
		flags = HL_RAZWI_HBW;
		razwi_offset = 0;
	} else {
		base = initiator->lbw_razwi_info_base;
		bw_type = "LBW";
		flags = HL_RAZWI_LBW;
		razwi_offset = RAZWI_LBW_OFFSET;
	}

	switch (type) {
	case RR_AW:
		base += RR_AW_OFFSET;
		flags |= (HL_RAZWI_WRITE | HL_RAZWI_RR);
		razwi_type = "RR_WRITE";
		break;
	case RR_AR:
		base += RR_AR_OFFSET;
		flags |= (HL_RAZWI_READ | HL_RAZWI_RR);
		razwi_type = "RR_READ";
		break;
	case ADEC_AW:
		base += ADDR_DECODER_AW_OFFSET;
		flags |= (HL_RAZWI_WRITE | HL_RAZWI_ADDR_DEC);
		razwi_type = "ADDR_DEC_WRITE";
		break;
	case ADEC_AR:
		base += ADDR_DECODER_AR_OFFSET;
		flags |= (HL_RAZWI_READ | HL_RAZWI_ADDR_DEC);
		razwi_type = "ADDR_DEC_READ";
		break;
	default:
		dev_err(hdev->dev, "Wrong razwi type (%u)\n", type);
		return false;
	}

	/* Check if RAZWI happened. If so, retrieve address and initiator id which caused it and
	 * return true.
	 */
	is_razwi_happened = RREG32(base + mmRTR_CTRL_CH_RAZWI_HBW_RR_RAZWI_AW_HAPPENED_ST);
	if (!is_razwi_happened)
		return false;

	addr_hi = RREG32(base + mmRTR_CTRL_CH_RAZWI_HBW_RR_RAZWI_AW_ADDR_HI);
	addr_lo = RREG32(base + mmRTR_CTRL_CH_RAZWI_HBW_RR_RAZWI_AW_ADDR_LO);
	razwi_addr = ((u64)addr_hi << 32) + addr_lo + razwi_offset;

	dev_err(hdev->dev, "%s %s : %s, address 0x%llX, captured id %u\n",
				bw_type, razwi_type, initiator->initiator_name, razwi_addr, eng_id);

	hl_handle_razwi(hdev, razwi_addr, &eng_id, 1, flags, event_mask);

	WREG32(base + mmRTR_CTRL_CH_RAZWI_HBW_RR_RAZWI_AW_HAPPENED_CLR, 1);

	return true;
}

static void gaudi3_check_for_razwi_per_type(struct hl_device *hdev,
						struct razwi_initiator_info *initiator, bool is_hbw,
						u16 eng_id, u64 *event_mask)
{
	gaudi3_razwi_status(hdev, initiator, RR_AW, is_hbw, eng_id, event_mask);
	gaudi3_razwi_status(hdev, initiator, RR_AR, is_hbw, eng_id, event_mask);
	gaudi3_razwi_status(hdev, initiator, ADEC_AW, is_hbw, eng_id, event_mask);
	gaudi3_razwi_status(hdev, initiator, ADEC_AR, is_hbw, eng_id, event_mask);
}

static void gaudi3_check_for_razwi(struct hl_device *hdev, struct razwi_initiator_info *initiator,
					u16 eng_id, u64 *event_mask)
{
	if (initiator->hbw_razwi_info_base)
		gaudi3_check_for_razwi_per_type(hdev, initiator, true, eng_id, event_mask);

	if (initiator->lbw_razwi_info_base)
		gaudi3_check_for_razwi_per_type(hdev, initiator, false, eng_id, event_mask);
}

static void gaudi3_check_for_shared_razwi(struct hl_device *hdev, struct razwi_initiator_info *info,
						u16 info_arr_size, u8 die, u8 initiator_idx,
						u16 eng_id, u64 *event_mask)
{
	u16 initiators_per_die = info_arr_size / MAX_NUM_OF_DIES;
	u16 idx = (die * initiators_per_die) + initiator_idx;

	gaudi3_check_for_razwi(hdev, &info[idx], eng_id, event_mask);
}

static void gaudi3_generic_check_for_hdcore_razwi(struct hl_device *hdev,
							struct razwi_initiator_info *info,
							u16 info_arr_size, u8 hdcore,
							u8 initiator_idx, u16 eng_id,
							u64 *event_mask)
{
	u16 initiators_per_hdcore = info_arr_size / (NUM_OF_HDCORES_PER_DIE * MAX_NUM_OF_DIES);
	u16 idx = (hdcore * initiators_per_hdcore) + initiator_idx;

	gaudi3_check_for_razwi(hdev, &info[idx], eng_id, event_mask);
}

static void gaudi3_check_for_tpc_razwi(struct hl_device *hdev, u8 hdcore, u8 initiator_idx,
					u16 eng_id, u64 *event_mask)
{
	/* maps hdcore 0, 2, 5, 7 to 0, 1, 2, 3 */
	static u8 const hdcore_idx_map[] = {0, 255, 1, 255, 255, 2, 255, 3};
	u16 arr_size = ARRAY_SIZE(tpc_razwi_info) - NUM_HDCORES_WITH_9_TPC;
	u8 idx;

	/* non redundant tpc */
	if (initiator_idx < NUM_OF_TPC_PER_HDCORE)
		return gaudi3_generic_check_for_hdcore_razwi(hdev, &tpc_razwi_info[0], arr_size,
				hdcore, initiator_idx, eng_id, event_mask);

	/* redundant tpc */
	idx = hdcore_idx_map[hdcore];

	/* does not suppose to happen but just in case */
	if (idx == 255) {
		dev_err(hdev->dev, "initiator is %u but hdcore is %u\n", initiator_idx, hdcore);
		return;
	}

	gaudi3_check_for_razwi(hdev, &tpc_razwi_info[arr_size + idx], eng_id, event_mask);
}

static void gaudi3_check_for_mme_razwi(struct hl_device *hdev, u8 hdcore, u16 eng_id,
					u64 *event_mask)
{
	u16 idx = hdcore * RAZWI_NUM_OF_INITIATORS_PER_MME;
	int i;

	for (i = 0 ; i < RAZWI_NUM_OF_INITIATORS_PER_MME ; i++, idx++)
		gaudi3_check_for_razwi(hdev, &mme_razwi_info[idx], eng_id, event_mask);
}

static void gaudi3_check_for_edma_razwi(struct hl_device *hdev, u8 hdcore, u16 eng_id,
					u64 *event_mask)
{
	switch (hdcore) {
	case 1:
		gaudi3_check_for_razwi(hdev, &edma_razwi_info[0], eng_id, event_mask);
		break;

	case 3:
		gaudi3_check_for_razwi(hdev, &edma_razwi_info[1], eng_id, event_mask);
		break;

	case 4:
		gaudi3_check_for_razwi(hdev, &edma_razwi_info[2], eng_id, event_mask);
		break;

	case 6:
		gaudi3_check_for_razwi(hdev, &edma_razwi_info[3], eng_id, event_mask);
		break;

	default:
		break;
	}
}

static void gaudi3_check_for_rot_razwi(struct hl_device *hdev, u8 hdcore, u8 initiator_idx,
					u16 eng_id, u64 *event_mask)
{
	switch (hdcore) {
	case 1:
		gaudi3_check_for_razwi(hdev, &rot_razwi_info[0 + initiator_idx], eng_id,
					event_mask);
		break;

	case 3:
		gaudi3_check_for_razwi(hdev, &rot_razwi_info[2 + initiator_idx], eng_id,
					event_mask);
		break;

	case 4:
		gaudi3_check_for_razwi(hdev, &rot_razwi_info[4 + initiator_idx], eng_id,
					event_mask);
		break;

	case 6:
		gaudi3_check_for_razwi(hdev, &rot_razwi_info[6 + initiator_idx], eng_id,
					event_mask);
		break;

	default:
		break;
	}
}

static void gaudi3_razwi_handler(struct hl_device *hdev,  enum razwi_initiztor razwi_initiator,
						u8 die, u8 hdcore, u8 initiator_idx, u16 eng_id,
						u64 *event_mask)
{
	/* razwi_initiator: type of initiator which can cause a razwi.
	 * die: die number.
	 * hdcore: hdcore number.
	 * initiator_idx: index of initiator inside the block.
	 */

	switch (razwi_initiator) {
	case RAZWI_NCH:
		gaudi3_check_for_shared_razwi(hdev, &nch_razwi_info[0],
					ARRAY_SIZE(nch_razwi_info), die, initiator_idx, eng_id,
					event_mask);
		break;

	case RAZWI_PIF:
		gaudi3_check_for_shared_razwi(hdev, &pif_razwi_info[0],
					ARRAY_SIZE(pif_razwi_info), die, initiator_idx, eng_id,
					event_mask);
		break;

	case RAZWI_PMMU:
		gaudi3_check_for_shared_razwi(hdev, &pmmu_razwi_info[0],
					ARRAY_SIZE(pmmu_razwi_info), die, initiator_idx, eng_id,
					event_mask);
		break;

	case RAZWI_PSOC:
		gaudi3_check_for_shared_razwi(hdev, &psoc_razwi_info[0],
					ARRAY_SIZE(psoc_razwi_info), die, initiator_idx, eng_id,
					event_mask);
		break;

	case RAZWI_PARC:
		gaudi3_check_for_shared_razwi(hdev, &parc_razwi_info[0],
					ARRAY_SIZE(parc_razwi_info), die, initiator_idx, eng_id,
					event_mask);
		break;

	case RAZWI_PDMA:
		gaudi3_check_for_shared_razwi(hdev, &pdma_razwi_info[0],
					ARRAY_SIZE(pdma_razwi_info), die, initiator_idx, eng_id,
					event_mask);
		break;

	case RAZWI_CPU:
		gaudi3_check_for_shared_razwi(hdev, &cpu_razwi_info[0],
					ARRAY_SIZE(cpu_razwi_info), die, initiator_idx, eng_id,
					event_mask);
		break;

	case RAZWI_GIC:
		gaudi3_check_for_shared_razwi(hdev, &gic_razwi_info[0],
					ARRAY_SIZE(gic_razwi_info), die, initiator_idx, eng_id,
					event_mask);
		break;

	case RAZWI_NIC:
		gaudi3_check_for_shared_razwi(hdev, &nic_razwi_info[0],
					ARRAY_SIZE(nic_razwi_info), die, initiator_idx, eng_id,
					event_mask);
		break;

	case RAZWI_STLB:
		gaudi3_generic_check_for_hdcore_razwi(hdev, &stlb_razwi_info[0],
					ARRAY_SIZE(stlb_razwi_info), hdcore, initiator_idx, eng_id,
					event_mask);
		break;

	case RAZWI_DEC:
		gaudi3_generic_check_for_hdcore_razwi(hdev, &dec_razwi_info[0],
					ARRAY_SIZE(dec_razwi_info), hdcore, initiator_idx, eng_id,
					event_mask);
		break;

	case RAZWI_ARC_FARM:
		gaudi3_generic_check_for_hdcore_razwi(hdev, &arc_farm_razwi_info[0],
					ARRAY_SIZE(arc_farm_razwi_info), hdcore, initiator_idx,
					eng_id, event_mask);
		break;

	case RAZWI_SM:
		gaudi3_generic_check_for_hdcore_razwi(hdev, &sm_razwi_info[0],
					ARRAY_SIZE(sm_razwi_info), hdcore, initiator_idx, eng_id,
					event_mask);
		break;

	case RAZWI_SDUP:
		gaudi3_generic_check_for_hdcore_razwi(hdev, &sdup_razwi_params[0],
					ARRAY_SIZE(sdup_razwi_params), hdcore, initiator_idx,
					eng_id, event_mask);
		break;

	case RAZWI_TPC:
		gaudi3_check_for_tpc_razwi(hdev, hdcore, initiator_idx, eng_id, event_mask);
		break;

	case RAZWI_MME:
		gaudi3_check_for_mme_razwi(hdev, hdcore, eng_id, event_mask);
		break;

	case RAZWI_EDMA:
		gaudi3_check_for_edma_razwi(hdev, hdcore, eng_id, event_mask);
		break;

	case RAZWI_ROT:
		gaudi3_check_for_rot_razwi(hdev, hdcore, initiator_idx, eng_id, event_mask);
		break;

	default:
		break;
	}
}

static u32 hdcore_type_to_hdcore(u32 die, enum hl_agg_hdcore_type hdcore_type)
{
	return (hdcore_type <= INT_HDCORE3) ? die * NUM_OF_HDCORES_PER_DIE + hdcore_type : 0;
}

static u16 eq_agg_header_to_engine_id(struct hl_agg_eq_header *agg_hdr)
{
	u32 die = agg_hdr->die_id, hdcore = hdcore_type_to_hdcore(die, agg_hdr->hdcore_type),
			instance = agg_hdr->comp_instance;
	enum hl_agg_component_type agg_component_type = agg_hdr->int_comp_type;
	u16 engine_id;

	switch (agg_component_type) {
	case INT_COMP_TYPE_ARC_FARM:
		/*
		 * TODO:
		 * The ARC_FARM interrupts are for the 2 ARC blocks per hdcore.
		 * Need to get the actual ARC based on the interrupt data, instead of arbitrarily
		 * selecting the first one (SW-121023).
		 */
		engine_id = GAUDI3_HDCORE0_ENGINE_ID_ARCF_0 + hdcore * NUM_ARC_SCHED_PER_HDCORE;
		break;

	case INT_COMP_TYPE_DEC:
		engine_id = GAUDI3_HDCORE0_ENGINE_ID_DEC_0 + hdcore * NUM_OF_DECODER_PER_HDCORE +
				instance;
		break;

	case INT_COMP_TYPE_EDMA:
		/*
		 * There are EDMA blocks only in HD 1/3/4/6, so need to divide hdcore by 2 to get
		 * the suitable engine id ([0] = HD1, [1] = HD3, [2] = HD4, [3] = HD6).
		 *
		 * TODO:
		 * The EDMA interrupts are for the 2 EDMA blocks per hdcore.
		 * Need to set the actual EDMA based on the interrupt data, instead of
		 * arbitrarily selecting the first one (SW-121023).
		 */
		engine_id = GAUDI3_HDCORE1_ENGINE_ID_EDMA_0 +
				(hdcore / 2) * NUM_OF_EDMA_PER_HDCORE + instance;
		break;

	case INT_COMP_TYPE_EDUP:
		/*
		 * TODO:
		 * There is currently no engine IDs for the ARC_DUP_ENG blocks, so use for now the
		 * corresponding ARC_FARM engine ID.
		 * Modify when dedicated ARC_DUP_ENG engines IDs are added (SW-121023).
		 */
		engine_id = GAUDI3_HDCORE0_ENGINE_ID_ARCF_0 + hdcore * NUM_ARC_SCHED_PER_HDCORE;
		break;

	case INT_COMP_TYPE_MME:
		engine_id = GAUDI3_HDCORE0_ENGINE_ID_MME_0 + hdcore;
		break;

	case INT_COMP_TYPE_NIC:
		engine_id = GAUDI3_DIE0_ENGINE_ID_NIC_0 + die * NIC_NUM_MACROS_PER_DIE + instance;
		break;

	case INT_COMP_TYPE_PDMA:
		/*
		 * TODO:
		 * The PDMA interrupts are for the 2 PDMA blocks per die.
		 * Need to get the actual PDMA based on the interrupt data, instead of arbitrarily
		 * selecting the first one (SW-121023).
		 */
		engine_id = GAUDI3_DIE0_ENGINE_ID_PDMA_0_CH_0 + die * NUM_OF_PDMA_CH_PER_DIE;
		break;

	case INT_COMP_TYPE_ROT:
		/*
		 * There are ROT blocks only in HD 1/3/4/6, so need to divide hdcore by 2 to get
		 * the suitable engine id ([0] = HD1, [1] = HD3, [2] = HD4, [3] = HD6).
		 */
		engine_id = GAUDI3_HDCORE1_ENGINE_ID_ROT_0 +
				(hdcore / 2) * NUM_OF_ROTATOR_PER_HDCORE + instance;
		break;

	case INT_COMP_TYPE_SOB:
		engine_id = GAUDI3_HDCORE0_ENGINE_ID_SM + hdcore;
		break;

	case INT_COMP_TYPE_TPC:
		if (instance < NUM_OF_TPC_PER_HDCORE)
			engine_id = GAUDI3_HDCORE0_ENGINE_ID_TPC_0 +
					(hdcore * NUM_OF_TPC_PER_HDCORE) + instance;
		else
			/*
			 * There are redundant TPC blocks only in HD 0/2/5/7, so need to divide
			 * hdcore by 2 to get the suitable engine id
			 * ([0] = HD0, [1] = HD2, [2] = HD5, [3] = HD7).
			 */
			engine_id = GAUDI3_HDCORE0_ENGINE_ID_TPC_8 + (hdcore / 2);
		break;

	default:
		engine_id = U16_MAX;
		break;
	}

	return engine_id;
}

static void gaudi3_sei_razwi_handler_no_fw(struct hl_device *hdev,
						struct hl_agg_eq_header *agg_hdr, u64 *event_mask)
{
	u8 die = agg_hdr->die_id, hdcore = (u8) hdcore_type_to_hdcore(die, agg_hdr->hdcore_type),
			initiator_idx = agg_hdr->comp_instance;
	enum hl_agg_component_type agg_component_type = agg_hdr->int_comp_type;
	u16 eng_id = eq_agg_header_to_engine_id(agg_hdr);

	switch (agg_component_type) {
	case INT_COMP_TYPE_PCIE:
	case INT_COMP_TYPE_CS:
		/* No need to handle razwi */
		break;

	case INT_COMP_TYPE_ARC_FARM:
		/*
		 * TODO:
		 * The ARC_FARM SEI interrupt is for the 2 ARC blocks per hdcore.
		 * Need to check the actual ARC based on the interrupt data, instead of checking
		 * both (SW-121023).
		 */
		gaudi3_razwi_handler(hdev, RAZWI_ARC_FARM, die, hdcore, 0, eng_id, event_mask);
		gaudi3_razwi_handler(hdev, RAZWI_ARC_FARM, die, hdcore, 1, eng_id + 1, event_mask);
		break;

	case INT_COMP_TYPE_DEC:
		gaudi3_razwi_handler(hdev, RAZWI_DEC, die, hdcore, initiator_idx, eng_id,
					event_mask);
		break;

	case INT_COMP_TYPE_EDMA:
		/*
		 * TODO:
		 * The EDMA SEI interrupt is for the 2 EDMA blocks per hdcore.
		 * Need to check the actual EDMA based on the interrupt data, instead of checking
		 * both (SW-121023).
		 */
		gaudi3_razwi_handler(hdev, RAZWI_EDMA, die, hdcore, 0, eng_id, event_mask);
		gaudi3_razwi_handler(hdev, RAZWI_EDMA, die, hdcore, 1, eng_id + 1, event_mask);
		break;

	case INT_COMP_TYPE_MME:
		gaudi3_razwi_handler(hdev, RAZWI_MME, die, hdcore, initiator_idx, eng_id,
					event_mask);
		break;

	case INT_COMP_TYPE_PDMA:
		/*
		 * TODO:
		 * The PDMA SEI interrupt is for the 2 PDMA blocks per die.
		 * Need to check the actual PDMA based on the interrupt data, instead of checking
		 * both (SW-121023).
		 */
		gaudi3_razwi_handler(hdev, RAZWI_PDMA, die, hdcore, 0, eng_id, event_mask);
		gaudi3_razwi_handler(hdev, RAZWI_PDMA, die, hdcore, 1,
					eng_id + NUM_OF_PDMA_CH_PER_GRP, event_mask);
		break;

	case INT_COMP_TYPE_TPC:
		gaudi3_razwi_handler(hdev, RAZWI_TPC, die, hdcore, initiator_idx, eng_id,
					event_mask);
		break;

	case INT_COMP_TYPE_ROT:
		gaudi3_razwi_handler(hdev, RAZWI_ROT, die, hdcore, initiator_idx, eng_id,
					event_mask);
		break;

	case INT_COMP_TYPE_STLB:
		gaudi3_razwi_handler(hdev, RAZWI_STLB, die, hdcore, initiator_idx, eng_id,
					event_mask);
		break;

	case INT_COMP_TYPE_PSOC:
		gaudi3_razwi_handler(hdev, RAZWI_PSOC, die, hdcore, initiator_idx, eng_id,
					event_mask);
		break;

	default:
		dev_err(hdev->dev, "Component type %u doesn't have razwi handler\n",
			agg_component_type);
		break;
	}
}

static void gaudi3_check_if_razwi_happened(struct hl_device *hdev)
{
}

static void gaudi3_no_fw_monitor(struct hl_device *hdev, bool *stop_monitor)
{
	bool pci_link_error = false;

	*stop_monitor = true;
	if (hdev->pldm && !hdev->enable_intr_aggr) {
		gaudi3_handle_axi_drain(hdev, &pci_link_error);
		*stop_monitor = pci_link_error;
	}
}

int gaudi3_alloc_irq_vectors(struct hl_device *hdev, unsigned int min_vecs,
			unsigned int max_vecs, unsigned int flags)
{
	return pci_alloc_irq_vectors(hdev->pdev, min_vecs, max_vecs, flags);
}

void gaudi3_free_irq_vectors(struct hl_device *hdev)
{
	pci_free_irq_vectors(hdev->pdev);
}

int gaudi3_irq_vector(struct hl_device *hdev, unsigned int nr)
{
	return pci_irq_vector(hdev->pdev, nr);
}

int gaudi3_scheduler_submit_buf(struct hl_device *hdev, u32 cpu_id, u32 queue_id, void *buf,
					u32 len)
{
	u64 reg_addr;
	u32 *_buf = (u32 *)buf;

	if (cpu_id >= CPU_ID_SCHED_MAX)
		return -EINVAL;

	if (queue_id) /* Currently only queue 0 is supported */
		return -EINVAL;

	reg_addr = gaudi3_arc_blocks_bases[cpu_id] + mmQMAN_ARC_AUX_DCCM_QUEUE_PUSH_REG_0 +
			queue_id * sizeof(u32);

	for (; len ; len -= sizeof(u32), ++_buf)
		WREG32(reg_addr, *_buf);

	return 0;
}

bool gaudi3_is_valid_dram_page_size(u32 page_size)
{
	return (page_size == PAGE_SIZE_1MB) || (page_size == PAGE_SIZE_32MB) ||
							(page_size == PAGE_SIZE_1GB);
}

int gaudi3_mmu_get_real_page_size(struct hl_device *hdev, struct hl_mmu_properties *mmu_prop,
					u32 page_size, u32 *real_page_size, bool is_dram_addr)
{
	if (is_dram_addr) {
		/*
		 * here we always use the original page size as it was already validated
		 * by the driver
		 */
		*real_page_size = page_size;
		return 0;
	}

	if ((page_size % mmu_prop->page_size) == 0) {
		*real_page_size = mmu_prop->page_size;
		return 0;
	}

	dev_err(hdev->dev, "page size of %u is not %uKB aligned, can't map\n",
						page_size, mmu_prop->page_size >> 10);

	return -EFAULT;
}

int gaudi3_get_monitor_dump(struct hl_device *hdev, void *data)
{
	return -EOPNOTSUPP;
}

static void gaudi3_pdma_mask_err_int(struct hl_device *hdev,
		u64 err_cause_reg, u32 err_ignore_msk, u64 err_int_mask_reg)
{
	u32 err_int_mask_val, err_cause_val = RREG32(err_cause_reg) & (~err_ignore_msk);

	if (err_cause_val) {
		err_int_mask_val = RREG32(err_int_mask_reg);
		WREG32(err_int_mask_reg, err_int_mask_val | err_cause_val);
	}
}

static u32 gaudi3_handle_pdma_module_sei_err(struct hl_device *hdev, u8 die, bool is_pqm)
{
	u64 err_cause_reg_offset, ch_err_cause_addr, ch_err_int_mask_addr, grp_addr, ch_addr;
	struct asic_fixed_properties *prop = &hdev->asic_prop;
	u32 err_cnt = 0, curr_err_cnt, ch_err_ignore_mask;
	const char * const *err_tbl;
	char pdma_channel_name[20];
	const char *module_name;
	int i, j;

	if (is_pqm) {
		err_cause_reg_offset = PDMA_CH_B_OFFSET + mmPDMA_CH_B_PQM_CH_ERR_STATUS;
		module_name = "PQM";
		ch_err_ignore_mask = 0;
		err_tbl = gaudi3_pdma_pqm_sei_err_cause;
	} else {
		err_cause_reg_offset = PDMA_CH_B_OFFSET + mmPDMA_CH_B_ERR_STATUS;
		module_name = "PDMA";
		/* Ignore valid bit */
		ch_err_ignore_mask = PDMA_CH_B_ERR_STATUS_VALID_M;
		err_tbl = gaudi3_pdma_sei_err_cause;
	}

	/* Loop on all groups in die */
	for (i = 0 ; i < NUM_OF_PDMA_GRP_PER_DIE ; i++) {
		grp_addr = gaudi3_pdma_grp_blocks_bases[(die * NUM_OF_PDMA_GRP_PER_DIE) + i];

		/* Loop on all channels in group */
		for (j = 0 ; j < prop->pdma_grp_ch_max ; j++) {
			ch_addr = grp_addr + (j * PDMA_CH_OFFSET);
			ch_err_cause_addr = ch_addr + err_cause_reg_offset;
			ch_err_int_mask_addr = ch_addr + PDMA_CH_B_OFFSET +
						mmPDMA_CH_B_ERR_INT_MASK;
			snprintf(pdma_channel_name, sizeof(pdma_channel_name) - 1,
					"%s%d_%d", module_name, i, j);

			if (!is_pqm) {
				/* Further ahead, we avoid clearing PDMA engine error indications-
				 * (clearing them will resume PDMA although STOP_ON_ERR's active).
				 * Yet, it causes the IRQ agg to storm us with the same event over
				 * and over, so instead of masking all PDMA SEI events we simply
				 * mask the error interrupts of the relevant PDMA engine channel.
				 */
				gaudi3_pdma_mask_err_int(hdev, ch_err_cause_addr,
						ch_err_ignore_mask, ch_err_int_mask_addr);
			}

			curr_err_cnt = gaudi3_handle_err_cause_reg(hdev, ch_err_cause_addr,
					false, err_tbl, pdma_channel_name, "SEI",
					ch_err_ignore_mask);
			if (curr_err_cnt) {
				err_cnt += curr_err_cnt;
				if (is_pqm)
					WREG32(grp_addr + PDMA_CMN_B_OFFSET +
							mmPDMA_CMN_B_PQM_CMN_B_SEI_STATUS,
							0x1 << j);
			}
		}
	}

	return err_cnt;
}

static u32 gaudi3_handle_pdma_sei_err(struct hl_device *hdev, u8 die)
{
	bool err_cnt = 0;

	err_cnt = gaudi3_handle_pdma_module_sei_err(hdev, die, false);
	err_cnt += gaudi3_handle_pdma_module_sei_err(hdev, die, true);

	return err_cnt;
}

static int gaudi3_validate_eqe_data_size(struct hl_device *hdev, u16 actual_size, u16 expected_size)
{
	if (actual_size != expected_size) {
		dev_err_ratelimited(hdev->dev, "EQ entry data size is %u while expecting %u\n",
					actual_size, expected_size);
		return -EINVAL;
	}

	return 0;
}

static u32 gaudi3_handle_arc_farm_sei_err(struct hl_device *hdev, u16 data_size,
					struct hl_eq_arcfarm_sei_data *arcfarm_sei_data)
{
	u32 err_cnt = 0;
	int rc;

	rc = gaudi3_validate_eqe_data_size(hdev, data_size, sizeof(*arcfarm_sei_data));
	if (rc)
		return 0;

	err_cnt = gaudi3_err_cause_iterator(hdev,
		lower_32_bits(le64_to_cpu(arcfarm_sei_data->arc0_wrapper_cause.intr_cause_data)),
					gaudi3_qm_arc_aux_sei_intr_cause, "ARC0", "SEI");

	err_cnt += gaudi3_err_cause_iterator(hdev,
		lower_32_bits(le64_to_cpu(arcfarm_sei_data->arc1_wrapper_cause.intr_cause_data)),
					gaudi3_qm_arc_aux_sei_intr_cause, "ARC1", "SEI");

	err_cnt += gaudi3_err_cause_iterator(hdev,
		lower_32_bits(le64_to_cpu(arcfarm_sei_data->internal_cause.intr_cause_data)),
					gaudi3_arc_farm_sei_err_cause, "ARC_FARM", "SEI");

	return err_cnt;
}

static u32 gaudi3_handle_decoder_sei_err(struct hl_device *hdev, u16 data_size,
				struct hl_eq_razwi_with_intr_cause_data *razwi_with_intr_cause)
{
	u32 err_mask;
	int rc;

	rc = gaudi3_validate_eqe_data_size(hdev, data_size, sizeof(*razwi_with_intr_cause));
	if (rc)
		return 0;

	err_mask = lower_32_bits(le64_to_cpu(razwi_with_intr_cause->intr_cause.intr_cause_data)) &
			VDEC_BRDG_CTRL_CAUSE_INTR_SEI_M;

	return gaudi3_err_cause_iterator(hdev, err_mask, gaudi3_decoder_intr_cause, "DEC", "SEI");
}

static u32 gaudi3_handle_pcie0_sei_err(struct hl_device *hdev, u16 data_size,
					struct hl_eq_pcie_sei_data *pcie_sei_data)
{
	u32 err_msk;
	int rc;

	rc = gaudi3_validate_eqe_data_size(hdev, data_size, sizeof(*pcie_sei_data));
	if (rc)
		return 0;

	if (pcie_sei_data->sei_type != PCIE_SEI_AXI_RESP_ERR)
		return 0;

	err_msk = lower_32_bits(le64_to_cpu(pcie_sei_data->intr_cause.intr_cause_data));

	return gaudi3_err_cause_iterator(hdev, err_msk, gaudi3_pcie_sei_err_cause, "PCIE", "SEI");
}

static u32 gaudi3_handle_qm_sei_err(struct hl_device *hdev, struct hl_eq_qm_sei_data *qm_sei_data,
					const char *engine)
{
	u32 err_num, err_msk;
	char buf[32];

	snprintf(buf, sizeof(buf), "%s_QM", engine);
	err_msk = lower_32_bits(le64_to_cpu(qm_sei_data->qm_cause.intr_cause_data)) &
			QMAN_GLBL_ERR_STS_MASK;
	err_num = gaudi3_err_cause_iterator(hdev, err_msk, gaudi3_qm_err_cause, buf, "SEI");

	snprintf(buf, sizeof(buf), "%s_QM_ARC_AUX", engine);
	err_msk = lower_32_bits(le64_to_cpu(qm_sei_data->arc_qm_cause.intr_cause_data));
	err_num += gaudi3_err_cause_iterator(hdev, err_msk, gaudi3_qm_arc_aux_sei_intr_cause, buf,
						"SEI");

	return err_num;
}

static u32 gaudi3_handle_edma_sei_err(struct hl_device *hdev, u16 data_size,
					struct hl_eq_edma_sei_data *edma_sei_data)
{
	u32 instance, channel, chn_data_idx, err_num = 0, err_mask, err_num_tmp;
	struct hl_eq_edma_chn_data *edma_chn_data;
	char buf[32];
	int rc;

	rc = gaudi3_validate_eqe_data_size(hdev, data_size, sizeof(*edma_sei_data));
	if (rc)
		return 0;

	for (instance = 0 ; instance < NUM_OF_EDMA_PER_HDCORE ; ++instance) {
		for (channel = 0 ; channel < NUM_OF_EDMA_CHANNELS ; ++channel) {
			chn_data_idx = instance * NUM_OF_EDMA_PER_HDCORE + channel;
			edma_chn_data = &edma_sei_data->chn_data[chn_data_idx];
			err_mask = le32_to_cpu(edma_chn_data->err_sts) &
					EDMA_CHN_ERR_STATUS_ENG_MASK;
			snprintf(buf, sizeof(buf), "EDMA%u_CH%u", instance, channel);
			err_num_tmp = gaudi3_err_cause_iterator(hdev, err_mask,
								gaudi3_edma_err_cause, buf, "SEI");
			if (err_num_tmp)
				dev_err_ratelimited(hdev->dev, "%s context ID: %u\n",
							buf, le16_to_cpu(edma_chn_data->ctx_id));
			err_num += err_num_tmp;
		}

		snprintf(buf, sizeof(buf), "EDMA%u", instance);
		err_num += gaudi3_handle_qm_sei_err(hdev, &edma_sei_data->qm_data[instance], buf);
	}

	return err_num;
}

static u32 handle_tpc_events(struct hl_device *hdev, struct hl_eq_tpc_data *tpc_data,
					enum hl_agg_grp_type type)
{
	u32 err_num, err_msk, cause, mask, smt_mask;
	char initiator_str[16] = {};
	char *type_str;
	int th;

	if (type == INT_GRP_TYPE_SEI) {
		mask = TPC_SEI_INTR_MASK;
		smt_mask = TPC_SMT_TH_SEI_INTR_MASK;
		type_str = "SEI";
	} else {
		mask = TPC_SPI_INTR_MASK;
		smt_mask = TPC_SMT_TH_SPI_INTR_MASK;
		type_str = "SPI";
	}

	err_msk = lower_32_bits(le64_to_cpu(tpc_data->intr_cause.intr_cause_data));
	err_msk &= mask;
	err_num = gaudi3_err_cause_iterator(hdev, err_msk, gaudi3_tpc_tpc_err_cause,
									"TPC", type_str);

	for (th = 0 ; th < NUM_OF_TPC_THREADS ; th++) {
		snprintf(initiator_str, sizeof(initiator_str), "TPC_TH%u", th);

		switch (th) {
		case 0:
			cause = le32_to_cpu(tpc_data->smt_th0_cause);
			break;
		case 1:
			cause = le32_to_cpu(tpc_data->smt_th1_cause);
			break;
		case 2:
			cause = le32_to_cpu(tpc_data->smt_th2_cause);
			break;
		case 3:
			cause = le32_to_cpu(tpc_data->smt_th3_cause);
			break;
		}
		cause &= smt_mask;
		err_num += gaudi3_err_cause_iterator(hdev, cause, gaudi3_tpc_smt_tpc_th_err_cause,
								initiator_str, type_str);
	}

	/*
	 * if err_num == 0 at this point - then this is spmu/bmon event that the driver don't care
	 * about so we just return 0 and don't print any error.
	 */
	return err_num;
}

static u32 handle_tpc_spi_events(struct hl_device *hdev, u16 data_size,
					struct hl_eq_tpc_spi_data *spi_data)
{
	u32 err_num;
	int rc;

	rc = gaudi3_validate_eqe_data_size(hdev, data_size, sizeof(struct hl_eq_tpc_spi_data));
	if (rc)
		return 0;

	err_num = handle_tpc_events(hdev, &spi_data->data, INT_GRP_TYPE_SPI);
	if (err_num)
		dev_err_ratelimited(hdev->dev, "TPC KERNEL ID: 0x%x\n",
				le16_to_cpu(spi_data->data.kernel_id));

	return err_num;
}

static u32 gaudi3_handle_mme_acc_event(struct hl_device *hdev, struct hl_eq_mme_acc_data *acc_data,
						char *event)
{
	char initiator_str[128] = {};
	u32 cause, err_num = 0;
	int i;

	snprintf(initiator_str, sizeof(initiator_str), "MME_ACC%u", acc_data->id);
	cause = le64_to_cpu(acc_data->intr_cause.intr_cause_data);
	err_num = gaudi3_err_cause_iterator(hdev, cause, gaudi3_mme_acc_intr_cause,
							initiator_str, event);
	for (i = MME_ACC_CTX_ID_CH0_SET0; i < MME_ACC_CTX_ID_MAX; i++) {
		u32 ch = i / 2, set = i % 2;

		if (acc_data->ctx_id[i])
			dev_err_ratelimited(hdev->dev,
					"MME ACC %s event context ch%u set%u: 0x%x\n",
						event, ch, set, le16_to_cpu(acc_data->ctx_id[i]));
	}
	return err_num;
}

static u32 gaudi3_handle_mme_spi_events(struct hl_device *hdev, u16 data_size,
					struct hl_eq_mme_spi_data *spi_data)
{
	struct hl_eq_mme_spmu_bmon *spmu_bmon_data = &spi_data->spmu_bmon_data;
	struct hl_eq_mme_acc_data *acc_data = &spi_data->acc_data;
	u32 cause, err_num = 0;
	int i, rc;

	rc = gaudi3_validate_eqe_data_size(hdev, data_size, sizeof(struct hl_eq_mme_spi_data));
	if (rc)
		return 0;

	switch (spi_data->type) {
	case MME_DATA_TYPE_CS_DBG:
		for (i = 0; i < CS_DBG_BMON_MAX; i++) {
			if (!spmu_bmon_data->data.cause[i])
				continue;

			cause = le32_to_cpu(spmu_bmon_data->data.cause[i]);
			if (i == CS_DBG_SPMU) {
				err_num += gaudi3_err_cause_iterator(hdev, cause,
					gaudi3_cs_dbg_spmu_pmintenset_el1, "MME SPMU", "SPI");
			} else {
				dev_err_ratelimited(hdev->dev,
					"MME BMON%u event. Trigger threshold is 0x%x\n",
						i - CS_DBG_BMON0, cause);
				err_num++;
			}
		}
		break;
	case MME_DATA_TYPE_ACC:
		err_num  = gaudi3_handle_mme_acc_event(hdev, acc_data, "SPI");
		break;
	default:
		break;
	}

	return err_num;
}

static u32 gaudi3_handle_mme_sei_err(struct hl_device *hdev, u16 data_size,
					struct hl_eq_mme_sei_data *sei_data)
{
	struct hl_eq_mme_ctrl_data *ctrl_data = &sei_data->control_data;
	struct hl_eq_mme_acc_data *acc_data = &sei_data->acc_data;
	struct hl_eq_mme_sbte_data *sbte = &sei_data->sbte_data;
	char initiator_str[128] = {};
	u32 cause, err_num = 0;
	int rc;

	rc = gaudi3_validate_eqe_data_size(hdev, data_size, sizeof(struct hl_eq_mme_sei_data));
	if (rc)
		return 0;

	switch (sei_data->type) {
	case MME_DATA_TYPE_SBTE:
		snprintf(initiator_str, sizeof(initiator_str), "MME_EU_%u SBTE%u",
						sbte->mme_eu_id, sbte->sbte_id);
		cause = le64_to_cpu(sbte->cause.intr_cause_data);
		err_num = gaudi3_err_cause_iterator(hdev, cause, gaudi3_mme_sbte_intr_cause,
								initiator_str, "SEI");
		if (err_num)
			dev_err_ratelimited(hdev->dev, "MME context ID: %u\n",
							le16_to_cpu(sbte->ctx_id));
		break;
	case MME_DATA_TYPE_ACC:
		err_num  = gaudi3_handle_mme_acc_event(hdev, acc_data, "SEI");
		break;
	case MME_DATA_TYPE_CTRL:
		cause = le64_to_cpu(ctrl_data->cause.intr_cause_data);
		err_num = gaudi3_err_cause_iterator(hdev, cause, gaudi3_mme_ctrl_lo_intr_cause,
								"MME_CTRL", "SEI");
		err_num += gaudi3_handle_qm_sei_err(hdev, &ctrl_data->qm_data, "MME");
		break;
	default:
		break;
	}

	return err_num;
}

static u32 hmmu_sei_event_get_dti_desc(struct hl_device *hdev, u64 syndrom_dti, char *str, u64 size)
{
	u64 id = FIELD_GET(GENMASK_ULL(3, 0), syndrom_dti);
	u64 opcode = FIELD_GET(GENMASK_ULL(7, 4), syndrom_dti);
	u64 va = FIELD_GET(GENMASK_ULL(43, 16), syndrom_dti);
	u64 pa = FIELD_GET(GENMASK_ULL(35, 16), syndrom_dti);
	u64 asid = FIELD_GET(GENMASK_ULL(57, 48), syndrom_dti);
	u64 sz = FIELD_GET(GENMASK_ULL(51, 48), syndrom_dti);
	u64 type = FIELD_GET(GENMASK_ULL(55, 52), syndrom_dti);
	u64 status = FIELD_GET(GENMASK_ULL(63, 60), syndrom_dti);

	switch (opcode) {
	case 0x0:
		snprintf(str, size,
			 "TRANS_REQ id: %llu, va: 0x%llx, asid: %llu", id, va, asid);
		break;
	case 0x1:
		snprintf(str, size,
			 "TRANS_RESP id: %llu, pa: 0x%llx, size: %llu, type: %llu, status: %llu",
			 id, pa, sz, type, status);
		break;
	case 0x2:
		snprintf(str, size,
			 "INV_VA_REQ id: %llu, va: 0x%llx, asid: %llu", id, va, asid);
		break;
	case 0x3:
		snprintf(str, size,
			 "INV_VA_RESP id: %llu, status %llu", id, status);
		break;
	case 0x4:
		snprintf(str, size,
			 "INV_ALL_REQ id: %llu, asid %llu", id, asid);
		break;
	case 0x5:
		snprintf(str, size,
			 "INV_ALL_RESP id %llu, status %llu", id, status);
		break;
	case 0x6:
		snprintf(str, size,
			 "FAULT_MSG_REQ id: %llu, va: 0x%llx, asid: %llu", id, va, asid);
		break;
	case 0x7:
		snprintf(str, size,
			 "FAULT_MSG_RESP, id %llu, status %llu", id, status);
		break;
	default:
		snprintf(str, size,
			 "TRANS id %llu, unknown code %llu", id, opcode);
		break;
	}

	return 1;
}

static u32 handle_hmmu_sei_events(struct hl_device *hdev, u16 data_size,
				  struct hl_eq_stlb_sei_data *sei_data)
{
	char stlb_str[256] = {0}, dtlb_str[256] = {0};
	u32 err_cnt = 0;

	if (gaudi3_validate_eqe_data_size(hdev, data_size, sizeof(*sei_data)))
		return 0;

	if (sei_data->cause.intr_cause_data & STLB_INTR_SEI_CAUSE_LBW_RSP_ERR_M) {
		snprintf(stlb_str, sizeof(stlb_str), "LBW resp error: address 0x%x, data: 0x%x",
			 le32_to_cpu(sei_data->lbw_data.addr),
			 le32_to_cpu(sei_data->lbw_data.data));
		err_cnt++;
	}

	if (sei_data->cause.intr_cause_data & STLB_INTR_SEI_CAUSE_PTW_RSP_ERR_M)
		err_cnt += hmmu_sei_event_get_dti_desc(hdev,
						le64_to_cpu(sei_data->fault_data.syndrom_dti),
						dtlb_str, sizeof(dtlb_str));

	dev_err(hdev->dev,
		"STLB info: %s, DTLB info: %s\n", stlb_str, dtlb_str);

	return err_cnt;
}

static u32 handle_tpc_sei_events(struct hl_device *hdev, u16 data_size,
					struct hl_eq_tpc_sei_data *sei_data)
{
	u32 err_num;
	int rc;

	rc = gaudi3_validate_eqe_data_size(hdev, data_size, sizeof(struct hl_eq_tpc_sei_data));
	if (rc)
		return 0;

	err_num = handle_tpc_events(hdev, &sei_data->data, INT_GRP_TYPE_SEI);
	if (err_num)
		dev_err_ratelimited(hdev->dev, "TPC KERNEL ID: 0x%x\n",
				le16_to_cpu(sei_data->data.kernel_id));

	err_num += gaudi3_handle_qm_sei_err(hdev, &sei_data->qm_data, "TPC");

	return err_num;
}

static u32 gaudi3_handle_rotator_sei_err(struct hl_device *hdev, u16 data_size,
						struct hl_eq_rot_sei_data *rot_sei_data)
{
	u32 err_msk, err_num;
	int rc;

	rc = gaudi3_validate_eqe_data_size(hdev, data_size, sizeof(*rot_sei_data));
	if (rc)
		return 0;

	err_msk = lower_32_bits(le64_to_cpu(rot_sei_data->cause.intr_cause_data)) &
			ROTATOR_MSS_SEI_CAUSE_MASK;
	err_num = gaudi3_err_cause_iterator(hdev, err_msk, gaudi3_rotator_sei_cause, "ROT", "SEI");

	err_num += gaudi3_handle_qm_sei_err(hdev, &rot_sei_data->qm_data, "ROT");

	return err_num;
}

static u32 gaudi3_handle_psoc_sei_err(struct hl_device *hdev, u16 data_size,
						struct hl_eq_psoc_sei_data *sei_data)
{
	u32 err_bits, err_num;
	int rc;

	rc = gaudi3_validate_eqe_data_size(hdev, data_size, sizeof(*sei_data));
	if (rc)
		return 0;

	err_bits = lower_32_bits(le64_to_cpu(sei_data->intr_cause.intr_cause_data)) &
				PSOC_GLBL_CONF2_SEI_INTR_MASK;
	err_num = gaudi3_err_cause_iterator(hdev, err_bits, gaudi3_psoc_sei_cause, "PSOC", "SEI");

	return err_num;
}

static void gaudi3_rotator_spi_err_sts_iterator(struct hl_device *hdev,
						struct hl_eq_rot_spi_data *rot_spi_data,
						u32 err_status, u32 err_id_offset,
						const char * const *err_tbl)
{
	u32 idx = 0, err_id;

	while (err_status) {
		if (err_status & 0x1) {
			err_id = idx + err_id_offset;
			dev_err_ratelimited(hdev->dev, "ROT %s. ctx_id %u\n",
						err_tbl[idx],
						le16_to_cpu(rot_spi_data->data.ctx_id[err_id]));
		}

		++idx;
		err_status >>= 1;
	}
}

static u32 gaudi3_handle_rotator_spi_err(struct hl_device *hdev, u16 data_size,
						struct hl_eq_rot_spi_data *rot_spi_data)
{
	u32 err_msk, err_num, err_status;
	int rc;

	rc = gaudi3_validate_eqe_data_size(hdev, data_size, sizeof(*rot_spi_data));
	if (rc)
		return 0;

	err_msk = lower_32_bits(le64_to_cpu(rot_spi_data->data.intr_cause.intr_cause_data)) &
			ROTATOR_MSS_SPI_CAUSE_MASK;
	err_num = gaudi3_err_cause_iterator(hdev, err_msk, gaudi3_rotator_spi_cause, "ROT", "SPI");

	if (err_msk & ROTATOR_MSS_SPI_CAUSE_IP_NUM_MASK) {
		err_status = le32_to_cpu(rot_spi_data->data.ip_num_cause) &
				ROTATOR_IP_NUM_ERR_STATUS_MASK;
		gaudi3_rotator_spi_err_sts_iterator(hdev, rot_spi_data, err_status,
							GAUDI3_ROTATOR_SPI_IP_NUM_ERR_ID_OFFSET,
							gaudi3_rotator_ip_numerical_err_sts);
	}

	if (err_msk & ROTATOR_MSS_SPI_CAUSE_RSB_MASK) {
		err_status = le32_to_cpu(rot_spi_data->data.rsb_err_cause) &
				ROTATOR_RSB_ERR_STATUS_MASK;
		gaudi3_rotator_spi_err_sts_iterator(hdev, rot_spi_data, err_status,
							GAUDI3_ROTATOR_SPI_RSB_ERR_ID_OFFSET,
							gaudi3_rotator_rsb_err_sts);
	}

	if (err_msk & ROTATOR_MSS_SPI_CAUSE_WCH_MASK) {
		err_status = le32_to_cpu(rot_spi_data->data.wch_err_cause) &
				ROTATOR_WCH_ERR_STATUS_MASK;
		gaudi3_rotator_spi_err_sts_iterator(hdev, rot_spi_data, err_status,
							GAUDI3_ROTATOR_SPI_WCH_ERR_ID_OFFSET,
							gaudi3_rotator_wch_err_sts);
	}

	return err_num;
}

static inline u32 gaudi3_handle_single_err_mask(struct hl_device *hdev, u32 err_msk, char *err_name)
{
	if (err_msk & 0x1) {
		dev_err_ratelimited(hdev->dev, "%s event\n", err_name);
		return 1;
	}

	return 0;
}

static u32 gaudi3_handle_pcie_spi_drain(struct hl_device *hdev,
						struct hl_eq_pcie_drain_ind_data *dc)
{
	u64 cause = le64_to_cpu(dc->intr_cause.intr_cause_data);
	u32 err_num = 0;

	if (cause & (PCIE_WRAP_AXI_DRAIN_IND_LBW_AXI_DRAIN_IND_M |
			PCIE_WRAP_AXI_DRAIN_IND_LBW_AXI_DRAIN_BP_IND_M)) {
		err_num++;
		dev_err_ratelimited(
				hdev->dev, "PCIE SPI LBW drain error WR 0x%llX, RD 0x%llX\n",
				le64_to_cpu(dc->drain_wr_addr_lbw),
				le64_to_cpu(dc->drain_rd_addr_lbw));
	}

	if (cause & (PCIE_WRAP_AXI_DRAIN_IND_HBW_AXI_DRAIN_IND_M |
			PCIE_WRAP_AXI_DRAIN_IND_HBW_AXI_DRAIN_BP_IND_M)) {
		err_num++;
		dev_err_ratelimited(
				hdev->dev, "PCIE SPI HBW drain error WR 0x%llX, RD 0x%llX\n",
				le64_to_cpu(dc->drain_wr_addr_hbw),
				le64_to_cpu(dc->drain_rd_addr_hbw));
	}

	return err_num;
}

static u32 gaudi3_handle_pcie0_spi_err(struct hl_device *hdev, u16 data_size,
					struct hl_eq_pcie_spi_data *pcie_spi_data)
{
	u32 err_num = 0, err_msk;
	int rc;

	rc = gaudi3_validate_eqe_data_size(hdev, data_size, sizeof(*pcie_spi_data));
	if (rc)
		return 0;

	switch (pcie_spi_data->spi_type) {
	case PCIE_SPI_FLR:
		err_msk = lower_32_bits(le64_to_cpu(pcie_spi_data->flr_cause.intr_cause_data));
		err_num = gaudi3_handle_single_err_mask(hdev, err_msk, "PCIE SPI FLR");
		break;

	case PCIE_SPI_APB_ACCESS_TIMEOUT:
		err_num = 1;
		dev_err_ratelimited(hdev->dev, "PCIE SPI APB access timeout error\n");
		break;

	case PCIE_SPI_FATAL_ERR:
		err_msk = lower_32_bits(le64_to_cpu(pcie_spi_data->fatal_error.intr_cause_data));
		err_num = gaudi3_handle_single_err_mask(hdev, err_msk, "PCIE SPI fatal");
		break;

	case PCIE_SPI_P2P_OR_MSIX_GW_INTR:
		err_msk = lower_32_bits(le64_to_cpu(pcie_spi_data->p2p_msix.p2p.intr_cause_data));
		err_num = gaudi3_handle_single_err_mask(hdev, err_msk, "PCIE SPI P2P");

		err_msk = lower_32_bits(
				le64_to_cpu(pcie_spi_data->p2p_msix.msix_gw.intr_cause_data));
		err_num += gaudi3_handle_single_err_mask(hdev, err_msk, "PCIE SPI MSIX gateway");
		break;

	case PCIE_SPI_DRAIN:
		err_num = gaudi3_handle_pcie_spi_drain(hdev, &pcie_spi_data->drain_cause);
		break;

	default:
		dev_err_ratelimited(hdev->dev, "Error: PCIE SPI unknown error type (%u)\n",
				pcie_spi_data->spi_type);
		break;
	}

	return err_num;
}

static u32 gaudi3_handle_decoder_spi(struct hl_device *hdev, u16 data_size,
					struct hl_eq_generic_spi_data *spi_data, u64 *event_mask)
{
	u32 irq_status, err_cnt;
	int rc;

	rc = gaudi3_validate_eqe_data_size(hdev, data_size, sizeof(*spi_data));
	if (rc)
		return 0;

	irq_status = lower_32_bits(le64_to_cpu(spi_data->cause.intr_cause_data)) & VCMD_SW_IRQ_MASK;

	err_cnt = gaudi3_err_cause_iterator(hdev, irq_status, gaudi3_decoder_spi_intr_cause, "DEC",
						"SPI");

	if (irq_status & VSI_CMD_SWREG17_SW_IRQ_CMDERR_M)
		*event_mask |= HL_NOTIFIER_EVENT_UNDEFINED_OPCODE;

	/*
	 * VCMD timeout interrupt is not caused directly by user, and therefore considered as a
	 * GENERAL_HW_ERR.
	 */
	if (irq_status & VSI_CMD_SWREG17_SW_IRQ_TIMEOUT_M) {
		*event_mask &= ~HL_NOTIFIER_EVENT_USER_ENGINE_ERR;
		*event_mask |= HL_NOTIFIER_EVENT_GENERAL_HW_ERR;
	}

	return err_cnt;
}

static u32 gaudi3_handle_nic_spi(struct hl_device *hdev, u32 macro_index, u16 data_size,
					struct hl_eq_nic_spi_data *nic_spi_data)
{
	struct gaudi3_device *gaudi3 = hdev->asic_specific;
	struct gaudi3_cn_aux_ops *aux_ops = &gaudi3->cn_aux_ops;
	struct hl_aux_dev *aux_dev = &hdev->cn.cn_aux_dev;
	int rc;

	rc = gaudi3_validate_eqe_data_size(hdev, data_size, sizeof(*nic_spi_data));
	if (rc)
		return 0;

	if (nic_spi_data->spi_type == NIC_SPI_BMON_SPMU)
		return gaudi3_cn_handle_bmon_spmu_event(hdev, macro_index);
	else if (aux_ops->spi_event_handler)
		/* NIC_SPI_SW_ERROR */
		return aux_ops->spi_event_handler(aux_dev, macro_index);

	return 0;
}

static void gaudi3_handle_ecc_event(struct hl_device *hdev, struct hl_eq_ecc_data *ecc_data)
{
	u64 ecc_address, ecc_syndrome;
	u8 memory_wrapper_idx;
	u32 block_base;

	ecc_address = le64_to_cpu(ecc_data->ecc_address);
	ecc_syndrome = le64_to_cpu(ecc_data->ecc_syndrom);
	memory_wrapper_idx = ecc_data->memory_wrapper_idx;
	block_base = FIELD_PREP(ECC_BLOCK_LBW_BASE_ADDR_M, le16_to_cpu(ecc_data->block_id));

	dev_err(hdev->dev,
		"ECC error detected. block base %#x. memory idx %u. address %#llx. syndrome: %#llx. critical %u.\n",
		block_base, memory_wrapper_idx, ecc_address, ecc_syndrome, ecc_data->is_critical);
}

static u32 gaudi3_handle_nic_status_event(struct hl_device *hdev,
				struct hl_eq_dynamic_entry *eq_dynamic_entry)
{
	u8 cmd, period;
	u64 mask;
	int port, rc;

	cmd = eq_dynamic_entry->nic_sts_req_data.cmd;
	mask = le64_to_cpu(eq_dynamic_entry->nic_sts_req_data.port_en_mask);
	period = eq_dynamic_entry->nic_sts_req_data.period;

	for (port = 0 ; port < NIC_NUMBER_OF_PORTS ; port++) {
		if (!(mask & BIT(port)))
			continue;
		rc = hl_cn_send_status(hdev, port, cmd, period);
		if (rc)
			return rc;
	}

	return 0;
}

static int gaudi3_handle_msg_event(struct hl_device *hdev,
				struct hl_eq_dynamic_entry *eq_dynamic_entry, u32 *reset_flags,
				u64 *event_mask)
{
	u16 event_type;
	u32 ctl;

	ctl = le32_to_cpu(eq_dynamic_entry->hdr.ctl);
	event_type = FIELD_GET(EQ_CTL_EVENT_TYPE_MASK, ctl);

	switch (event_type) {
	case EQ_EVENT_NIC_STS_REQUEST:
		return gaudi3_handle_nic_status_event(hdev, eq_dynamic_entry);
	default:
		return 0;
	}
}

static const char *gaudi3_get_interrupt_grp_name(u8 int_grp_type)
{
	if (int_grp_type >= INT_GRP_TYPE_MAX)
		return "N/A";

	return gaudi3_interrupt_grp_name[int_grp_type];
}

static const char *gaudi3_get_interrupt_comp_name(u8 int_comp_type)
{
	if (int_comp_type >= INT_COMP_TYPE_MAX)
		return "N/A";

	return gaudi3_interrupt_comp_name[int_comp_type];
}

static const char *gaudi3_get_interrupt_hdcore_name(u8 hdcore_type)
{
	if (hdcore_type >= INT_HDCORE_MAX)
		return "N/A";

	return gaudi3_interrupt_hdcore_name[hdcore_type];
}

static void gaudi3_print_hw_event_info(struct hl_device *hdev, struct hl_agg_eq_header *agg_hdr)
{
	dev_dbg(hdev->dev, "Received H/W event [%s, DIE%d, %s, instance %d, %s]\n",
			gaudi3_get_interrupt_comp_name(agg_hdr->int_comp_type),
			agg_hdr->die_id,
			gaudi3_get_interrupt_hdcore_name(agg_hdr->hdcore_type),
			agg_hdr->comp_instance,
			gaudi3_get_interrupt_grp_name(agg_hdr->int_grp_type));
}

static void gaudi3_set_reset_flags_and_event_mask(struct hl_device *hdev,
							struct hl_agg_eq_header *agg_hdr,
							u32 *reset_flags, u64 *event_mask)
{
	enum hl_agg_component_type agg_component_type = agg_hdr->int_comp_type;
	bool fw_reset = false, hard_reset = false, compute_reset = false;
	enum hl_agg_grp_type agg_grp_type = agg_hdr->int_grp_type;

	if (agg_grp_type == INT_GRP_TYPE_DERR) {
		*event_mask = HL_NOTIFIER_EVENT_CRITICL_HW_ERR;
		if (hdev->asic_prop.fw_security_enabled)
			fw_reset = true;
		else
			hard_reset = true;
		goto out;
	}

	switch (agg_component_type) {
	case INT_COMP_TYPE_ARC_FARM:
	case INT_COMP_TYPE_DEC:
	case INT_COMP_TYPE_EDMA:
	case INT_COMP_TYPE_EDUP:
	case INT_COMP_TYPE_MME:
	case INT_COMP_TYPE_PDMA:
	case INT_COMP_TYPE_ROT:
	case INT_COMP_TYPE_SOB:
	case INT_COMP_TYPE_TPC:
		*event_mask = HL_NOTIFIER_EVENT_USER_ENGINE_ERR;
		compute_reset = true;
		break;
	case INT_COMP_TYPE_NIC:
		/* NIC SPI events are not errors. */
		/* TODO: re-enable when NIC SEI interrupt after reset is cleared (SW-151293) */
		if (0 && agg_grp_type == INT_GRP_TYPE_SEI) {
			*event_mask = HL_NOTIFIER_EVENT_USER_ENGINE_ERR;
			hard_reset = true;
		}
		break;
	case INT_COMP_TYPE_MC:
		*event_mask = HL_NOTIFIER_EVENT_CRITICL_HW_ERR;
		hard_reset = true;
		break;
	case INT_COMP_TYPE_CPU:
	case INT_COMP_TYPE_PARC:
		*event_mask = HL_NOTIFIER_EVENT_CRITICL_FW_ERR;
		hard_reset = true;
		break;
	case INT_COMP_TYPE_PMMU:
	case INT_COMP_TYPE_STLB:
		if (agg_grp_type == INT_GRP_TYPE_SPI) {
			*event_mask = HL_NOTIFIER_EVENT_USER_ENGINE_ERR;
			/* device reset is not required */
		} else {
			*event_mask = HL_NOTIFIER_EVENT_GENERAL_HW_ERR;
			hard_reset = true;
		}
		break;
	default:
		*event_mask = HL_NOTIFIER_EVENT_GENERAL_HW_ERR;
		hard_reset = true;
		break;
	}

out:
	if (compute_reset) {
		*reset_flags = HL_DRV_RESET_DELAY;
		*event_mask |= HL_NOTIFIER_EVENT_DEVICE_RESET;
	} else if (hard_reset) {
		*reset_flags = HL_DRV_RESET_HARD | HL_DRV_RESET_FW_FATAL_ERR | HL_DRV_RESET_DELAY;
		*event_mask |= HL_NOTIFIER_EVENT_DEVICE_RESET;
	} else if (fw_reset) {
		*reset_flags = HL_DRV_RESET_HARD | HL_DRV_RESET_FW_FATAL_ERR |
				HL_DRV_RESET_BYPASS_REQ_TO_FW;
		*event_mask |= HL_NOTIFIER_EVENT_DEVICE_RESET |
				HL_NOTIFIER_EVENT_DEVICE_UNAVAILABLE;
	}
}

static u32 gaudi3_handle_derr_event(struct hl_device *hdev,
				struct hl_eq_dynamic_entry *eq_dynamic_entry, u64 *event_mask)
{
	u16 data_size = le16_to_cpu(eq_dynamic_entry->hdr.size);
	int rc;

	rc = gaudi3_validate_eqe_data_size(hdev, data_size, sizeof(eq_dynamic_entry->ecc_data));
	if (rc)
		return 0;

	gaudi3_handle_ecc_event(hdev, &eq_dynamic_entry->ecc_data);

	return 1;
}

static u32 gaudi3_cs_sei_err_cause_iterator(struct hl_device *hdev,
						struct hl_eq_cs_sei_data *sei_data)
{
	u32 cause = lower_32_bits(le64_to_cpu(sei_data->cause.intr_cause_data));
	int i, err_count = 0;

	for (i = 0 ; i < 32 && cause ; i++) {
		switch (BIT(i) & cause) {
		case 0:
			/* no error */
			continue;
		case CACHE_MAIN_SEI_CAUSE_REG_C2M_R_SLV_ERR_ORIG_WRITE_M:
			dev_err_ratelimited(hdev->dev, "CS SEI error: %s, addr 0x%llx\n",
					    gaudi3_cs_sei_err_cause[i],
					    le64_to_cpu(sei_data->err_data.slv_err_addr));
			break;
		case CACHE_MAIN_SEI_CAUSE_REG_POISON_LOCAL_AR_M:
		case CACHE_MAIN_SEI_CAUSE_REG_POISON_LOCAL_AWW_M:
		case CACHE_MAIN_SEI_CAUSE_REG_POISON_LOCAL_M_WR_M:
		case CACHE_MAIN_SEI_CAUSE_REG_POISON_REMOTE_AR_M:
		case CACHE_MAIN_SEI_CAUSE_REG_POISON_REMOTE_AWW_M:
			dev_err_ratelimited(hdev->dev,
					    "CS SEI error: %s, addr 0x%llx, id 0x%llx\n",
					    gaudi3_cs_sei_err_cause[i],
					    le64_to_cpu(sei_data->err_data.poison_data.addr),
					    le64_to_cpu(sei_data->err_data.poison_data.id));
			break;
		case CACHE_MAIN_SEI_CAUSE_REG_FAR_HOST_REDUC_NUM_ERR_M:
			dev_err_ratelimited(hdev->dev,
					    "CS SEI error: %s, err 0x%x, info 0x%llx, addr 0x%llx\n",
					    gaudi3_cs_sei_err_cause[i],
					    sei_data->err_data.far_data.num_err,
					    le64_to_cpu(sei_data->err_data.far_data.info),
					    le64_to_cpu(sei_data->err_data.far_data.addr));
			break;
		case CACHE_MAIN_SEI_CAUSE_REG_CLOSE_HOST_REDUC_NUM_ERR_M:
			dev_err_ratelimited(hdev->dev,
					    "CS SEI error: %s, err 0x%x, info 0x%llx, addr 0x%llx\n",
					    gaudi3_cs_sei_err_cause[i],
					    sei_data->err_data.close_data.num_err,
					    le64_to_cpu(sei_data->err_data.close_data.info),
					    le64_to_cpu(sei_data->err_data.close_data.addr));
			break;
		case CACHE_MAIN_SEI_CAUSE_REG_AAB_REDUC_NUM_ERR_M:
			dev_err_ratelimited(hdev->dev,
					    "CS SEI error: %s, num_err 0x%x\n",
					    gaudi3_cs_sei_err_cause[i],
					    sei_data->err_data.aab_num_err);
			break;
		case CACHE_MAIN_SEI_CAUSE_REG_DN_CONV_NUM_ERR_M:
			dev_err_ratelimited(hdev->dev,
					    "CS SEI error: %s, dn_conv_id 0x%llx\n",
					    gaudi3_cs_sei_err_cause[i],
					    le64_to_cpu(sei_data->err_data.dn_conv_id));
			break;
		default:
			dev_err_ratelimited(hdev->dev,
					    "CS SEI error: %s\n", gaudi3_cs_sei_err_cause[i]);
			break;
		}

		cause &= ~BIT(i);
		err_count++;
	}

	return err_count;
}

static u32 gaudi3_handle_cs_sei_err(struct hl_device *hdev, u16 data_size,
					struct hl_eq_cs_sei_data *sei_data)
{
	int rc;

	rc = gaudi3_validate_eqe_data_size(hdev, data_size, sizeof(*sei_data));
	if (rc)
		return 0;


	return gaudi3_cs_sei_err_cause_iterator(hdev, sei_data);
}

static int gaudi3_validate_eq_agg_header(struct hl_device *hdev, struct hl_agg_eq_header *agg_hdr)
{
	struct asic_fixed_properties *prop = &hdev->asic_prop;

	if (agg_hdr->int_grp_type >= INT_GRP_TYPE_MAX) {
		dev_err_ratelimited(hdev->dev,
					"eq_agg_header: interrupt group type %u is invalid\n",
					agg_hdr->int_grp_type);
		return -EINVAL;
	}

	if (agg_hdr->int_comp_type >= INT_COMP_TYPE_MAX) {
		dev_err_ratelimited(hdev->dev,
					"eq_agg_header: interrupt component type %u is invalid\n",
					agg_hdr->int_comp_type);
		return -EINVAL;
	}

	if (agg_hdr->die_id >= prop->num_of_dies) {
		dev_err_ratelimited(hdev->dev, "eq_agg_header: die id %u is invalid\n",
					agg_hdr->die_id);
		return -EINVAL;
	}

	if (agg_hdr->hdcore_type >= INT_HDCORE_MAX) {
		dev_err_ratelimited(hdev->dev, "eq_agg_header: hdcore type %u is invalid\n",
					agg_hdr->hdcore_type);
		return -EINVAL;
	}

	/* Max possible instance value is 8 and it is for TPC */
	if (agg_hdr->comp_instance >= NUM_HDCORE0_TPC) {
		dev_err_ratelimited(hdev->dev, "eq_agg_header: component instance %u is invalid\n",
					agg_hdr->comp_instance);
		return -EINVAL;
	}

	return 0;
}

static void gaudi3_handle_razwi_info(struct hl_device *hdev, struct hl_eq_razwi_regs *r,
						char *type, u16 eng_id, u8 flags, u64 *event_mask)
{
	u64 addr = ((u64)le32_to_cpu(r->hi_reg) << 32) + le32_to_cpu(r->lo_reg);

	dev_err(hdev->dev, "%s RAZWI happened: addr 0x%llX, id 0x%X", type, addr, r->id);

	hl_handle_razwi(hdev, addr, &eng_id, 1, flags, event_mask);
}

static void gaudi3_handle_razwi(struct hl_device *hdev, struct hl_eq_razwi_rtr_data *rd, u16 eng_id,
					u64 *event_mask)
{
	if (rd->lbw.rr_aw.razwi_happened)
		gaudi3_handle_razwi_info(hdev, &rd->lbw.adec_ar, "LBW RR AW", eng_id,
				HL_RAZWI_LBW | HL_RAZWI_RR | HL_RAZWI_WRITE,
				event_mask);

	if (rd->lbw.rr_ar.razwi_happened)
		gaudi3_handle_razwi_info(hdev, &rd->lbw.adec_ar, "LBW RR AR", eng_id,
				HL_RAZWI_LBW | HL_RAZWI_RR | HL_RAZWI_READ,
				event_mask);

	if (rd->lbw.adec_aw.razwi_happened)
		gaudi3_handle_razwi_info(hdev, &rd->lbw.adec_ar, "LBW ADEC AW", eng_id,
				HL_RAZWI_LBW | HL_RAZWI_ADDR_DEC | HL_RAZWI_WRITE,
				event_mask);

	if (rd->lbw.adec_ar.razwi_happened)
		gaudi3_handle_razwi_info(hdev, &rd->lbw.adec_ar, "LBW ADEC AR", eng_id,
				HL_RAZWI_LBW | HL_RAZWI_ADDR_DEC | HL_RAZWI_READ,
				event_mask);

	if (rd->hbw.rr_aw.razwi_happened)
		gaudi3_handle_razwi_info(hdev, &rd->lbw.adec_ar, "HBW RR AW", eng_id,
				HL_RAZWI_HBW | HL_RAZWI_RR | HL_RAZWI_WRITE,
				event_mask);

	if (rd->hbw.rr_ar.razwi_happened)
		gaudi3_handle_razwi_info(hdev, &rd->lbw.adec_ar, "HBW RR AR", eng_id,
				HL_RAZWI_HBW | HL_RAZWI_RR | HL_RAZWI_READ,
				event_mask);

	if (rd->hbw.adec_aw.razwi_happened)
		gaudi3_handle_razwi_info(hdev, &rd->lbw.adec_ar, "HBW ADEC AW", eng_id,
				HL_RAZWI_HBW | HL_RAZWI_ADDR_DEC | HL_RAZWI_WRITE,
				event_mask);

	if (rd->hbw.adec_ar.razwi_happened)
		gaudi3_handle_razwi_info(hdev, &rd->lbw.adec_ar, "HBW ADEC AR", eng_id,
				HL_RAZWI_HBW | HL_RAZWI_ADDR_DEC | HL_RAZWI_READ,
				event_mask);
}

static void gaudi3_sei_razwi_handler(struct hl_device *hdev, struct hl_eq_dynamic_entry *eq,
					u64 *event_mask)
{
	enum hl_agg_component_type agg_component_type = eq->agg_hdr.int_comp_type;
	u16 eng_id = eq_agg_header_to_engine_id(&eq->agg_hdr);

	switch (agg_component_type) {
	case INT_COMP_TYPE_CS:
	case INT_COMP_TYPE_D2D_MAC:
	case INT_COMP_TYPE_PCIE:
	case INT_COMP_TYPE_PLL:
		/* No need to handle razwi */
		break;

	case INT_COMP_TYPE_ARC_FARM:
		gaudi3_handle_razwi(hdev, &eq->arcfarm_sei_data.rtr_data, eng_id, event_mask);
		break;

	case INT_COMP_TYPE_CPU:
		gaudi3_handle_razwi(hdev, &eq->cpu_sei_data.rtr_data, eng_id, event_mask);
		break;

	case INT_COMP_TYPE_DEC:
		gaudi3_handle_razwi(hdev, &eq->razwi_with_intr_cause.rtr_data, eng_id, event_mask);
		break;

	case INT_COMP_TYPE_EDMA:
		gaudi3_handle_razwi(hdev, &eq->edma_sei_data.rtr_data[SEDMA_ID0], eng_id,
					event_mask);
		gaudi3_handle_razwi(hdev, &eq->edma_sei_data.rtr_data[SEDMA_ID1], eng_id + 1,
					event_mask);
		break;

	case INT_COMP_TYPE_MME:
		gaudi3_handle_razwi(hdev, &eq->mme_sei_data.sbte_data.rtr_data, eng_id, event_mask);
		gaudi3_handle_razwi(hdev, &eq->mme_sei_data.acc_data.rtr_data, eng_id, event_mask);
		gaudi3_handle_razwi(hdev,
				&eq->mme_sei_data.control_data.qm_rtr_data[MME_QM_RAZWI_RD], eng_id,
				event_mask);
		gaudi3_handle_razwi(hdev,
				&eq->mme_sei_data.control_data.qm_rtr_data[MME_QM_RAZWI_WR], eng_id,
				event_mask);
		break;

	case INT_COMP_TYPE_PARC:
		gaudi3_handle_razwi(hdev, &eq->parc_sei_data.rtr_data, eng_id, event_mask);
		break;

	case INT_COMP_TYPE_PDMA:
		gaudi3_handle_razwi(hdev, &eq->pdma_sei_data.spdma_data[SPDMA_ID0].rtr_data, eng_id,
					event_mask);
		gaudi3_handle_razwi(hdev, &eq->pdma_sei_data.spdma_data[SPDMA_ID0].rtr_data,
					eng_id + NUM_OF_PDMA_CH_PER_GRP, event_mask);
		break;

	case INT_COMP_TYPE_TPC:
		gaudi3_handle_razwi(hdev, &eq->tpc_sei_data.rtr_data, eng_id, event_mask);
		break;

	case INT_COMP_TYPE_ROT:
		gaudi3_handle_razwi(hdev, &eq->rot_sei_data.rtr_data, eng_id, event_mask);
		break;

	case INT_COMP_TYPE_STLB:
		gaudi3_handle_razwi(hdev, &eq->stlb_sei_data.rtr_data, eng_id, event_mask);
		break;

	case INT_COMP_TYPE_PSOC:
		gaudi3_handle_razwi(hdev, &eq->psoc_sei_data.rtr_data, eng_id, event_mask);
		break;

	default:
		dev_err(hdev->dev, "Component type %u doesn't have razwi handler\n",
			agg_component_type);
		break;
	}
}

static u32 gaudi3_handle_cpu_sei_err(struct hl_device *hdev, u16 data_size,
					struct hl_eq_cpu_sei_data *cpu_sei_data)
{
	int rc;

	rc = gaudi3_validate_eqe_data_size(hdev, data_size, sizeof(struct hl_eq_cpu_sei_data));
	if (rc)
		return 0;

	return gaudi3_err_cause_iterator(hdev,
			lower_32_bits(le64_to_cpu(cpu_sei_data->intr_cause.intr_cause_data)),
			gaudi3_cpu_sei_intr_cause, "CPU", "SEI");
}

static u32 gaudi3_handle_parc_sei_err(struct hl_device *hdev, u16 data_size,
					struct hl_eq_parc_sei_data *parc_sei_data)
{
	int rc;

	rc = gaudi3_validate_eqe_data_size(hdev, data_size, sizeof(struct hl_eq_parc_sei_data));
	if (rc)
		return 0;

	return gaudi3_err_cause_iterator(hdev,
			lower_32_bits(le64_to_cpu(parc_sei_data->intr_cause.intr_cause_data)),
			gaudi3_parc_sei_intr_cause, "PARC", "SEI");
}

static u32 gaudi3_handle_d2d_mac_sei_err(struct hl_device *hdev, u16 data_size,
					struct hl_eq_d2dmac_sei_data *d2d_mac_sei_data)
{
	u32 err_cnt;
	int rc;

	rc = gaudi3_validate_eqe_data_size(hdev, data_size, sizeof(struct hl_eq_d2dmac_sei_data));
	if (rc)
		return 0;

	err_cnt = gaudi3_err_cause_iterator(hdev,
			lower_32_bits(le64_to_cpu(d2d_mac_sei_data->intr_cause[0].intr_cause_data)),
			gaudi3_d2d_mac_sei_intr_cause1, "D2D_MAC", "SEI");

	err_cnt += gaudi3_err_cause_iterator(hdev,
			lower_32_bits(le64_to_cpu(d2d_mac_sei_data->intr_cause[1].intr_cause_data)),
			gaudi3_d2d_mac_sei_intr_cause2, "D2D_MAC", "SEI");

	return err_cnt;
}

static u32 gaudi3_handle_d2d_phy_sei_err(struct hl_device *hdev, u16 data_size,
						struct hl_eq_intr_cause *intr_cause)
{
	u32 err_mask;
	int rc;

	rc = gaudi3_validate_eqe_data_size(hdev, data_size, sizeof(struct hl_eq_intr_cause));
	if (rc)
		return 0;

	err_mask = lower_32_bits(le64_to_cpu(intr_cause->intr_cause_data));

	return gaudi3_err_cause_iterator(hdev, err_mask, gaudi3_d2d_phy_sei_intr_cause,
							"D2D_PHY", "SEI");
}

static u32 gaudi3_handle_pll_sei_err(struct hl_device *hdev, u16 data_size,
					struct hl_eq_pll_sei_data *pll_sei_cause)
{
	char err_str[32];
	u32 err_msk;
	int rc;

	rc = gaudi3_validate_eqe_data_size(hdev, data_size, sizeof(struct hl_eq_pll_sei_data));
	if (rc)
		return 0;

	err_msk = lower_32_bits(le64_to_cpu(pll_sei_cause->intr_cause.intr_cause_data));

	snprintf(err_str, sizeof(err_str) - 1, "PLL %u lock lost\n", pll_sei_cause->index);

	return gaudi3_handle_single_err_mask(hdev, err_msk, err_str);
}

static u32 gaudi3_handle_sei_event(struct hl_device *hdev,
				struct hl_eq_dynamic_entry *eq_dynamic_entry, u64 *event_mask)
{
	struct hl_agg_eq_header *agg_hdr = &eq_dynamic_entry->agg_hdr;
	struct gaudi3_device *gaudi3 = hdev->asic_specific;
	struct gaudi3_cn_aux_ops *aux_ops = &gaudi3->cn_aux_ops;
	u16 data_size = le16_to_cpu(eq_dynamic_entry->hdr.size);
	struct hl_aux_dev *aux_dev = &hdev->cn.cn_aux_dev;
	enum hl_agg_component_type agg_component_type;
	u32 die, instance, err_cnt = 0;

	agg_component_type = eq_dynamic_entry->agg_hdr.int_comp_type;
	die = eq_dynamic_entry->agg_hdr.die_id;
	instance = eq_dynamic_entry->agg_hdr.comp_instance;

	switch (agg_component_type) {
	case INT_COMP_TYPE_ARC_FARM:
		err_cnt = gaudi3_handle_arc_farm_sei_err(hdev, data_size,
							&eq_dynamic_entry->arcfarm_sei_data);
		break;
	case INT_COMP_TYPE_CPU:
		err_cnt = gaudi3_handle_cpu_sei_err(hdev, data_size,
							&eq_dynamic_entry->cpu_sei_data);
		break;
	case INT_COMP_TYPE_D2D_MAC:
		err_cnt = gaudi3_handle_d2d_mac_sei_err(hdev, data_size,
							&eq_dynamic_entry->d2dmac_sei_data);
		break;
	case INT_COMP_TYPE_D2D_PHY:
		err_cnt = gaudi3_handle_d2d_phy_sei_err(hdev, data_size,
							&eq_dynamic_entry->intr_cause);
		break;
	case INT_COMP_TYPE_DEC:
		err_cnt = gaudi3_handle_decoder_sei_err(hdev, data_size,
							&eq_dynamic_entry->razwi_with_intr_cause);
		break;
	case INT_COMP_TYPE_EDMA:
		err_cnt = gaudi3_handle_edma_sei_err(hdev, data_size,
							&eq_dynamic_entry->edma_sei_data);
		break;
	case INT_COMP_TYPE_NIC:
		if (aux_ops->sei_err_event_handler)
			err_cnt = aux_ops->sei_err_event_handler(aux_dev,
							die * NIC_NUM_MACROS_PER_DIE + instance);
		break;
	case INT_COMP_TYPE_PARC:
		err_cnt = gaudi3_handle_parc_sei_err(hdev, data_size,
							&eq_dynamic_entry->parc_sei_data);
		break;
	case INT_COMP_TYPE_PCIE:
		err_cnt = gaudi3_handle_pcie0_sei_err(hdev, data_size,
					&eq_dynamic_entry->pcie_sei_data);
		break;
	case INT_COMP_TYPE_PDMA:
		err_cnt = gaudi3_handle_pdma_sei_err(hdev, die);
		break;
	case INT_COMP_TYPE_PLL:
		err_cnt = gaudi3_handle_pll_sei_err(hdev, data_size,
							&eq_dynamic_entry->pll_sei_data);
		break;
	case INT_COMP_TYPE_CS:
		err_cnt = gaudi3_handle_cs_sei_err(hdev, data_size, &eq_dynamic_entry->cs_sei_data);
		break;
	case INT_COMP_TYPE_STLB:
		err_cnt = handle_hmmu_sei_events(hdev, data_size, &eq_dynamic_entry->stlb_sei_data);
		break;
	case INT_COMP_TYPE_TPC:
		err_cnt = handle_tpc_sei_events(hdev, data_size, &eq_dynamic_entry->tpc_sei_data);
		break;
	case INT_COMP_TYPE_MME:
		err_cnt = gaudi3_handle_mme_sei_err(hdev, data_size,
							&eq_dynamic_entry->mme_sei_data);
		break;
	case INT_COMP_TYPE_ROT:
		err_cnt = gaudi3_handle_rotator_sei_err(hdev, data_size,
							&eq_dynamic_entry->rot_sei_data);
		break;
	case INT_COMP_TYPE_PSOC:
		err_cnt = gaudi3_handle_psoc_sei_err(hdev, data_size,
							&eq_dynamic_entry->psoc_sei_data);
		break;
	default:
		break;
	}

	if (hdev->fw_components & FW_TYPE_BOOT_CPU)
		gaudi3_sei_razwi_handler(hdev, eq_dynamic_entry, event_mask);
	else
		gaudi3_sei_razwi_handler_no_fw(hdev, agg_hdr, event_mask);

	hl_check_for_glbl_errors(hdev);

	return err_cnt;
}

static u32 gaudi3_handle_spi_event(struct hl_device *hdev,
				struct hl_eq_dynamic_entry *eq_dynamic_entry, u64 *event_mask)
{
	u16 data_size = le16_to_cpu(eq_dynamic_entry->hdr.size);
	enum hl_agg_component_type agg_component_type;
	u32 die, hdcore, instance, err_cnt = 0;

	agg_component_type = eq_dynamic_entry->agg_hdr.int_comp_type;
	die = eq_dynamic_entry->agg_hdr.die_id;
	hdcore = hdcore_type_to_hdcore(die, eq_dynamic_entry->agg_hdr.hdcore_type);
	instance = eq_dynamic_entry->agg_hdr.comp_instance;

	switch (agg_component_type) {
	case INT_COMP_TYPE_DEC:
		err_cnt = gaudi3_handle_decoder_spi(hdev, data_size, &eq_dynamic_entry->spi_data,
							event_mask);
		break;
	case INT_COMP_TYPE_NIC:
		err_cnt = gaudi3_handle_nic_spi(hdev, die * NIC_NUM_MACROS_PER_DIE + instance,
						data_size, &eq_dynamic_entry->nic_spi_data);
		break;
	case INT_COMP_TYPE_PCIE:
		err_cnt = gaudi3_handle_pcie0_spi_err(hdev, data_size,
							&eq_dynamic_entry->pcie_spi_data);
		break;
	case INT_COMP_TYPE_PMMU:
		err_cnt = handle_pmmu_events(hdev, die, event_mask);
		break;
	case INT_COMP_TYPE_STLB:
		err_cnt = handle_hmmu_spi_events(hdev, data_size, &eq_dynamic_entry->stlb_spi_data,
						 hdcore, die, event_mask);
		break;
	case INT_COMP_TYPE_TPC:
		err_cnt = handle_tpc_spi_events(hdev, data_size, &eq_dynamic_entry->tpc_spi_data);
		break;
	case INT_COMP_TYPE_MME:
		err_cnt = gaudi3_handle_mme_spi_events(hdev, data_size,
							&eq_dynamic_entry->mme_spi_data);
		break;
	case INT_COMP_TYPE_ROT:
		err_cnt = gaudi3_handle_rotator_spi_err(hdev, data_size,
							&eq_dynamic_entry->rot_spi_data);
		break;
	default:
		break;
	}

	hl_check_for_glbl_errors(hdev);

	return err_cnt;
}

static void gaudi3_capture_engine_err(struct hl_device *hdev, struct hl_agg_eq_header *agg_hdr,
					u64 event_mask, u32 err_cnt)
{
	u16 engine_id;

	if (!(event_mask & HL_NOTIFIER_EVENT_USER_ENGINE_ERR))
		return;

	engine_id = eq_agg_header_to_engine_id(agg_hdr);
	if (engine_id == U16_MAX)
		return;

	hl_capture_engine_err(hdev, engine_id, (u16) err_cnt);
}

static int gaudi3_handle_hw_event(struct hl_device *hdev,
				struct hl_eq_dynamic_entry *eq_dynamic_entry,
				u32 *reset_flags, u64 *event_mask)
{
	struct hl_agg_eq_header *agg_hdr = &eq_dynamic_entry->agg_hdr;
	enum hl_agg_grp_type agg_grp_type = agg_hdr->int_grp_type;
	u32 err_cnt = 0;
	int rc;

	gaudi3_print_hw_event_info(hdev, agg_hdr);

	rc = gaudi3_validate_eq_agg_header(hdev, agg_hdr);
	if (rc)
		return rc;

	/*
	 * Set initial values of reset flags and notifier event mask per event/component types.
	 * A specific event handler can update them afterwards if needed.
	 */
	gaudi3_set_reset_flags_and_event_mask(hdev, agg_hdr, reset_flags, event_mask);

	switch (agg_grp_type) {
	case INT_GRP_TYPE_DERR:
		err_cnt = gaudi3_handle_derr_event(hdev, eq_dynamic_entry, event_mask);
		break;
	case INT_GRP_TYPE_SEI:
		err_cnt = gaudi3_handle_sei_event(hdev, eq_dynamic_entry, event_mask);
		break;
	case INT_GRP_TYPE_SPI:
		err_cnt = gaudi3_handle_spi_event(hdev, eq_dynamic_entry, event_mask);
		break;
	default:
		break;
	}

	if (!err_cnt) {
		dev_err(hdev->dev, "No error cause\n");
		return -EIO;
	}

	gaudi3_capture_engine_err(hdev, agg_hdr, *event_mask, err_cnt);

	return 0;
}

static void gaudi3_notifier_events_and_device_reset(struct hl_device *hdev, u32 reset_flags,
							u64 event_mask, u16 event_id)
{
	bool skip_reset_on_fw_events = (!hdev->hard_reset_on_fw_events &&
						!(reset_flags & HL_DRV_RESET_BYPASS_REQ_TO_FW));

	if (reset_flags || event_mask)
		dev_dbg(hdev->dev, "reset_flags %#x, event_mask %#llx\n", reset_flags, event_mask);

	if (!reset_flags || skip_reset_on_fw_events)
		goto skip_device_reset;

	hl_device_cond_reset(hdev, reset_flags, event_mask);

	return;

skip_device_reset:
	if (event_mask)
		hl_notifier_event_send_all(hdev, event_mask);
	if (event_id != U16_MAX)
		hl_fw_unmask_irq(hdev, event_id);
}

int gaudi3_handle_eqe(struct hl_device *hdev, struct hl_eq_dynamic_entry *eq_dynamic_entry)
{
	u32 ctl, reset_flags = 0;
	u16 event_id = U16_MAX;
	u64 event_mask = 0;
	bool is_hw_event;
	int rc;

	ctl = le32_to_cpu(eq_dynamic_entry->hdr.ctl);
	is_hw_event = !!FIELD_GET(EQ_CTL_EVENT_MODE_MASK, ctl);

	if (is_hw_event) {
		event_id = le16_to_cpu(eq_dynamic_entry->agg_hdr.event_id);
		rc = gaudi3_handle_hw_event(hdev, eq_dynamic_entry, &reset_flags, &event_mask);
	} else {
		rc = gaudi3_handle_msg_event(hdev, eq_dynamic_entry, &reset_flags, &event_mask);
	}

	gaudi3_notifier_events_and_device_reset(hdev, reset_flags, event_mask, event_id);

	return rc;
}

